import {currentBrief,briefPlanningContext,applyBriefCommand,assertBriefApproval,suggestBrief} from './creative-brief-core.js';
import {currentScreenplay,screenplayContext,assertScreenplayApproval} from './screenplay-core.js';
import {applyProductionRecord,recordDependencies} from './production-records-core.js';
import {renderProductionLibrary,bindProductionLibrary,renderProductionBindings} from './production-library.js';
import {migrateDeviceDraft} from './cloud-migration.js';
import {createAPIClient} from './api-client.js';
import {createDevice,listDevice,getDevice,patchDevice,saveDevice,addDeviceAsset,deviceAssets,commandScreenplayDevice} from './device-drafts.js';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stages = ['Brief','Story','Cast & World','Storyboard','Production','Edit & Review','Export'];
const stageIds = ['brief','story','cast','storyboard','production','edit','export'];
const state = {config:{capabilities:{}},projects:[],project:null,assets:[],approvals:[],skills:[],shot:null,skill:null,refs:[],messages:[],picker:null,pickerIndex:0,busy:false,format:'short_film',activity:[],scopeChanged:false};
const main = $('#main');
const blobUrls=new Map();
const local=()=>state.project?.isLocal===true;
let deviceProjects=[];
let migrationBusy=false;
const localSkills=['storyboard','character','camera','lighting','continuity','lip-sync','fix-shot'].map(id=>({id,name:id,version:'draft-1',description:'Add '+id.replaceAll('-',' ')+' direction to your draft',active:true}));
function signedIn(){return !!state.config.user||state.config.mode==='demo';}
function requireLogin(){if(signedIn())return true;$('#login-dialog').showModal();return false;}
function renderAuth(){document.querySelector('.admin-link').hidden=!state.config.user?.isAdmin;const button=$('#auth-button');button.hidden=state.config.mode==='demo';button.textContent=state.config.user?'Sign out':'Sign in';}

let toastTimer;
function toast(message){$('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',6500);}
const api=createAPIClient();
const list=(data,key)=>Array.isArray(data)?data:data?.[key]||[];
const projectFrom=data=>data.project||data;
const key=()=>`director:draft:${state.project?.id||'welcome'}`;
function draft(){try{return localStorage.getItem(key())||'';}catch{return '';}}
function saveDraft(value){try{localStorage.setItem(key(),value);}catch{/* Draft remains in current input if storage is unavailable. */}}
function remember(id){try{localStorage.setItem('director:lastProject',id);}catch{}}
function selectedShot(){return (state.project?.shots||[]).find(s=>s.id===state.shot);}
function stage(){return state.project?.stage||'brief';}
function markActivity(message){state.activity.push({message,time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})});}
async function save(fields){if(local()){state.project=await patchDevice(state.project,fields);deviceProjects=await listDevice();markActivity('Draft saved on this device.');return state.project;}const data=await api(`/api/projects/${encodeURIComponent(state.project.id)}`,{method:'PATCH',body:{...fields,expectedVersion:state.project.version}});state.project=projectFrom(data);markActivity('Project changes saved.');return state.project;}
async function loadProject(id){if(id.startsWith('device-')){const project=await getDevice(id);if(!project)return toast('That device draft is unavailable.');state.project=project;state.assets=await loadDeviceAssets(id);state.shot=project.shots[0]?.id||null;state.messages=project.notes||[];state.refs=[];state.skill=null;state.skills=localSkills;remember(id);render();return;}const previous=state.project;try{const data=await api(`/api/projects/${encodeURIComponent(id)}`);const candidate=projectFrom(data);const [assets,approvals]=await Promise.all([api(`/api/projects/${encodeURIComponent(id)}/assets`),api(`/api/projects/${encodeURIComponent(id)}/approvals`)]);state.project=candidate;state.assets=list(assets,'assets');state.approvals=list(approvals,'approvals');state.shot=state.project.shots?.[0]?.id||null;state.messages=state.project.notes||[];state.refs=[];state.skill=null;remember(id);render();}catch(error){state.project=previous;toast(error.message);}}
function render(){if($('#project-costs'))$('#project-costs').hidden=!state.project;const cloud=$('#cloud-save');cloud.hidden=!local();cloud.disabled=migrationBusy;cloud.textContent=migrationBusy?'Saving…':'Save to workspace';cloud.onclick=saveToWorkspace;$('#mode').textContent=local()?'On this device':state.config.mode==='demo'?'Local demo':'Workspace';document.body.classList.toggle('in-studio',['production','edit','export'].includes(stage())&&!!state.project);$('#notice').textContent=local()?'Draft saved on this device · not uploaded to your account':state.config.mode==='demo'?'Local development workspace · no paid generation.':state.project?.importState?.status==='awaiting_media'?'This cloud copy has pending references. Reopen its device draft and choose Save to workspace to resume.':!state.config.user?'Start a draft now. Sign in when you’re ready to save it to your workspace.':''; $('#project-name').textContent=state.project?.title||'Your next story starts here';if(!state.project)return renderWelcome();renderWorkspace();}
function renderWelcome(){main.innerHTML=`<section class="welcome"><div class="eyebrow">A film begins with an idea</div><h1>Tell me about<br>your film.</h1><p class="intro">Bring a premise, a script, or a moment you can’t stop thinking about. Shape it into a film, one deliberate decision at a time.</p><div class="formats" aria-label="Project format">${[['short_film','Short film'],['music_video','Music video'],['advertisement','Advertisement']].map(([id,label])=>`<button data-format="${id}" aria-pressed="${state.format===id}">${label}</button>`).join('')}</div><form id="start-form" class="brief-box"><label for="premise" class="small">Your idea</label><textarea id="premise" required placeholder="A night-shift train attendant finds a letter addressed to someone she lost…">${esc(draft())}</textarea><div class="brief-footer"><span class="small muted">Start with the story.<br>No media is generated on submission.</span><button type="submit" class="primary">${signedIn()?'Create project →':'Start draft →'}</button></div></form><section class="resume"><div class="eyebrow">Continue your work</div>${[...deviceProjects,...state.projects].length?[...deviceProjects,...state.projects].slice(0,6).map(p=>`<div class="resume-row"><div><strong>${esc(p.title)}</strong><small>${p.isLocal?'On this device · ':''}${esc(stages[stageIds.indexOf(p.stage)]||'Brief')} · ${esc(p.format||'Short film').replaceAll('_',' ')}</small></div><button data-open="${esc(p.id)}">Open project</button></div>`).join(''):'<p class="muted small">Your saved projects will appear here.</p>'}</section></section>`;
main.querySelectorAll('[data-format]').forEach(button=>button.onclick=()=>{saveDraft($('#premise').value);state.format=button.dataset.format;renderWelcome();});main.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>loadProject(button.dataset.open));$('#premise').oninput=e=>saveDraft(e.target.value);$('#start-form').onsubmit=async e=>{e.preventDefault();const premise=$('#premise').value.trim();if(!premise)return;if(!signedIn()){try{const project=await createDevice({premise,format:state.format});deviceProjects=await listDevice();await loadProject(project.id);toast('Draft saved on this device. No cloud upload or generation started.');}catch(error){toast(error.message);}return;}const button=e.submitter;button.disabled=true;button.textContent='Creating…';try{const data=await api('/api/projects',{method:'POST',body:{title:premise.slice(0,65),premise,format:state.format}});const p=projectFrom(data);state.projects.unshift(p);await loadProject(p.id);toast('Project created. Review your brief before planning.');}catch(error){toast(error.message);button.disabled=false;button.textContent='Create project →';}};}
function stageNavigation(){return `<nav class="stages" aria-label="Film stages">${stages.map((name,i)=>`<button class="stage ${stage()===stageIds[i]?'active':''}" data-stage="${stageIds[i]}" ${stage()===stageIds[i]?'aria-current="step"':''}><span class="number">${String(i+1).padStart(2,'0')}</span>${name}</button>`).join('')}</nav>`;}
function messagesHTML(){return state.messages.map(m=>`<div class="director-message ${m.role==='You'?'user':'assistant'}"><small>${esc(m.role)}</small><div class="bubble">${esc(m.text)}</div></div>`).join('');}
function assetUrl(a){return a?.url||'';}
function shotAsset(shot){if(!shot)return null;return state.assets.find(a=>a.id===shot.clipAssetId)||state.assets.find(a=>a.id===shot.referenceAssetId)||state.assets.find(a=>a.shotId===shot.id&&a.mime?.startsWith('video/'))||state.assets.find(a=>a.shotId===shot.id&&a.mime?.startsWith('image/'));}
function thumb(shot){const a=shotAsset(shot);return a?.mime.startsWith('image/')?`<img src="${esc(a.url)}" alt="">`:`<span class="thumb-placeholder">${a?.mime.startsWith('video/')?'▶':'▧'}</span>`;}
function railHTML(production){const p=state.project;return `<aside class="rail" id="rail" aria-label="Project navigation"><div class="rail-heading"><strong>${production?esc(p.title):'Create a film'}</strong><span>${production?`${p.duration}s film`:local()?'Device draft':'Workspace'}</span></div>${production?`<details class="stage-switch"><summary>Production · change stage</summary>${stageNavigation()}</details><h3>Scenes & shots <span>${p.shots.length}</span></h3><div class="scene-list">${p.shots.length?p.shots.map((shot,i)=>`<button class="scene-row ${shot.id===state.shot?'selected':''}" data-shot="${esc(shot.id)}"><span class="scene-thumb">${thumb(shot)}</span><span class="scene-copy"><strong>${String(i+1).padStart(2,'0')} · ${esc(shot.title)}</strong><small>${shot.duration}s · v${shot.version}</small></span></button>`).join(''):'<p class="muted small">Your planned shots will appear here.</p>'}</div>`:stageNavigation()}<h3>Cast & world <button class="text-button" data-go="cast">Open library</button></h3><div class="cast-grid">${state.assets.filter(a=>['character_identity','location','wardrobe'].includes(a.role)).slice(0,6).map(a=>`<button class="cast-tile" data-reference="${esc(a.id)}">${a.mime?.startsWith('image/')?`<img src="${esc(a.url)}" alt="">`:'<span>▧</span>'}<small>${esc(a.name)}</small></button>`).join('')||'<p class="muted small">No references yet</p>'}</div><h3>Project references</h3><div class="reference-list">${state.assets.map(a=>`<button class="asset-item" data-reference="${esc(a.id)}"><span>▧</span><span>${esc(a.name)}<small>${esc(a.role).replaceAll('_',' ')} · v${a.version}</small></span></button>`).join('')}</div><button id="rail-upload" class="rail-attach">+ Add reference</button>${production?`<h3>Production state</h3><div class="production-state">${local()?'Device draft · no generation':'Generation awaits validated routes'}<small>${state.shot?'Selected shot ready for direction':'Plan your first shot'}</small></div>`:''}</aside>`;}
function renderWorkspace(){const p=state.project,shot=selectedShot(),production=['production','edit','export'].includes(stage());
 if(stage()==='brief')return renderBriefing();
 main.innerHTML=`<div class="workspace ${production?'production':''}">${railHTML(production)}<section class="canvas" aria-label="Film workspace">${production?productionContent():`<div class="canvas-title"><div><h1>${esc(stages[stageIds.indexOf(stage())])}</h1><p>${esc(p.title)}</p></div><span class="status">${local()?'Device draft':`Version ${p.version}`}</span></div>${stageContent()}`}</section><aside class="director" id="director" aria-label="Director panel"><div class="director-head"><div><h2>Creative Director</h2><small>${shot?'Selected shot · '+esc(shot.title):'Project direction'}</small></div><div class="row"><button id="activity-toggle" aria-expanded="false">View activity</button><button class="close-sheet" id="close-director" aria-label="Close Director">×</button></div></div><div class="director-content"><div class="director-message assistant"><div class="bubble">${directorIntro()}</div></div><div id="messages">${messagesHTML()}</div><div class="context"><b>Current selection</b><p>${shot?`${esc(shot.title)} · v${shot.version}<br>${esc(shot.constraints||'No locked constraints recorded')}`:'Whole project'}</p><small>${local()?'Direction stays on this device.':'A verified estimate is required before generation.'}</small></div><div class="activity" id="activity" hidden>${state.activity.map(a=>`<div>${esc(a.time)} · ${esc(a.message)}</div>`).join('')||'No production activity yet.'}</div></div>${composer()}<p class="composer-note">${local()?'Notes and references stay on this device.':'Selecting a skill does not start a paid job.'}</p></aside>${mobileTools()}</div>`;bindWorkspace();bindMedia();}
function mobileTools(){return `<div class="mobile-tools"><button id="mobile-project">Project & stages</button><button id="mobile-director" class="primary">${stage()==='brief'?'Film brief':'Talk to Director'}</button></div>`;}
function renderBriefing(){const p=state.project,cover=state.assets.find(a=>a.mime?.startsWith('image/'));main.innerHTML=`<div class="workspace briefing">${railHTML(false)}<section class="brief-conversation"><header class="brief-title"><div class="brief-header-row"><h1>Your film direction.</h1><button type="button" id="brief-project-settings" aria-expanded="false" aria-controls="director">Project settings</button></div><p>Review the proposal, change what matters, and continue to your story.</p></header><div class="brief-transcript">${compactBriefHTML()}${state.messages.map(m=>`<div class="brief-bubble ${m.role==='You'?'person':'guide'}">${esc(m.text)}</div>`).join('')}</div>${composer()}<p class="composer-note">${local()?'This is your device draft. Nothing has been uploaded or generated.':'No video generation starts from a message alone.'}</p></section><aside class="director brief-inspector" id="director" aria-label="Film brief"><div class="director-head"><h2>Film brief · Draft</h2><div class="row"><button id="activity-toggle" aria-expanded="false">View activity</button><button class="close-sheet" id="close-director" aria-label="Close Director">×</button></div></div>${cover?`<div class="brief-cover"><img src="${esc(cover.url)}" alt="Uploaded project reference"></div>`:''}<details class="film-brief-summary"><summary>Project summary</summary><h2>${esc(p.title)}</h2>${[['Format',p.format.replaceAll('_',' ')],['Duration',p.duration+' seconds'],['Language',p.language],['Direction',p.direction||'Not specified'],['Storage',local()?'On this device':'Workspace']].map(([k,v])=>`<div class="property"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</details><details class="brief-details"><summary>Edit film brief</summary>${stageContent()}</details><div class="activity" id="activity" hidden>${state.activity.map(a=>`<div>${esc(a.message)}</div>`).join('')||'No activity yet.'}</div></aside>${mobileTools()}</div>`;bindWorkspace();}
function productionContent(){const p=state.project,shot=selectedShot(),a=shotAsset(shot),total=p.shots.reduce((n,s)=>n+s.duration,0);return `<header class="studio-toolbar"><div class="breadcrumbs">${esc(p.title)} <span>/</span> <b>${shot?esc(shot.title):'Production'}</b></div><div class="review-tools"><button id="compare-takes" disabled title="No generated takes available">Compare takes</button><button id="prepare-proposal" ${shot?'':'disabled'}>Request change</button><span class="status">${a?'Uploaded reference · not a generated take':'Awaiting media'}</span></div></header><div class="media-stage"><div class="viewer-wrap">${a?.mime.startsWith('video/')?`<video id="studio-player" preload="metadata" playsinline src="${esc(a.url)}" aria-label="Uploaded clip preview"></video>`:a?.mime.startsWith('image/')?`<img id="studio-still" src="${esc(a.url)}" alt="Uploaded shot reference">`:`<div class="viewer-empty"><span>▧</span><h2>${shot?'Add a reference for this shot':'Plan your first shot'}</h2><p>${shot?'Choose your own image or footage to review it here. No take has been generated.':'Build a storyboard, then develop each performance and frame.'}</p><button id="viewer-add" ${shot?'':'disabled'}>+ Add image or footage</button></div>`}<div class="viewer-meta">${shot?`${esc(shot.title)} · ${shot.duration}s planned`:''}</div></div><div class="viewer-transport"><button id="player-toggle" aria-label="Play preview" ${a?.mime.startsWith('video/')?'':'disabled'}>▶</button><span id="player-time">00:00</span><input id="player-seek" aria-label="Preview position" type="range" min="0" max="1000" value="0" ${a?.mime.startsWith('video/')?'':'disabled'}><button id="player-fullscreen" aria-label="Fullscreen preview" ${a?'':'disabled'}>⛶</button></div></div><section class="timeline-panel"><header><b>${stage()==='edit'?'Assembly & review':'Shot sequence'}</b><span>${p.shots.length} shots · ${total}s planned</span><button data-go="storyboard">Edit storyboard</button></header><div class="timeline-strip">${p.shots.map((s,i)=>`<button class="timeline-shot ${state.shot===s.id?'selected':''}" data-shot="${esc(s.id)}"><span class="timeline-thumb">${thumb(s)}</span><span>${String(i+1).padStart(2,'0')} · ${esc(s.title)}</span><small>${s.duration}s</small></button>`).join('')||'<p class="muted small">Your shot sequence will appear here.</p>'}</div><div class="audio-lanes">${[['dialogue','Dialogue'],['master_song','Music'],['ambience','Ambience']].map(([role,label])=>{const assets=state.assets.filter(a=>a.role===role&&a.mime?.startsWith('audio/'));return `<div class="audio-lane"><label>${label}</label><div class="lane-track">${assets.map(a=>`<button data-reference="${esc(a.id)}">${esc(a.name)}</button>`).join('')||'<span>No audio added</span>'}</div></div>`;}).join('')}</div></section><section class="shot-details-bar">${shot?`<span>${esc(shot.framing||'Framing not set')} · ${esc(shot.camera||'Camera not set')}</span><button data-go="storyboard">Shot specification</button>`:''}${stage()==='export'?'<p>Hosted export is not connected. You can download this draft and its references below.</p><button id="download-draft">Download draft JSON</button>':''}</section>`;}
function bindMedia(){const video=$('#studio-player'),play=$('#player-toggle'),seek=$('#player-seek');if(video){const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;play.onclick=()=>video.paused?video.play().catch(()=>toast('This clip could not play. Try another compatible MP4.')):video.pause();video.onplay=()=>{play.textContent='Ⅱ';play.setAttribute('aria-label','Pause preview');};video.onpause=()=>{play.textContent='▶';play.setAttribute('aria-label','Play preview');};video.ontimeupdate=()=>{if(Number.isFinite(video.duration)){seek.value=video.currentTime/video.duration*1000;$('#player-time').textContent=time(video.currentTime)+' / '+time(video.duration);}};seek.oninput=()=>{if(Number.isFinite(video.duration))video.currentTime=Number(seek.value)/1000*video.duration;};video.onerror=()=>toast('Preview unavailable. This browser may not support the clip format.');}if($('#player-fullscreen'))$('#player-fullscreen').onclick=()=>$('.viewer-wrap').requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this browser.'));if($('#viewer-add'))$('#viewer-add').onclick=()=>{openUpload();$('#upload-scope').value='shot';$('#upload-role').value='shot_reference';};if($('#download-draft'))$('#download-draft').onclick=downloadDraft;}
function directorIntro(){if(stage()==='brief')return 'Start with what matters: the story, its audience and how it should feel. You can edit the brief here before preparing a treatment.';if(stage()==='story')return 'Review the treatment and scene structure. An approval records this specific version; later edits require a new review.';if(stage()==='cast')return 'Build a reference pack with clear roles. An attached image is a reference, not a guarantee of identity preservation.';if(stage()==='storyboard')return 'Define the action, framing and duration of each shot. Keep the story readable before committing to production.';return 'Accepted references and boards come first. Prepare a proposal for the selected shot; unknown costs and unvalidated routes remain blocked.';}
function stageContent(){const p=state.project;const shots=p.shots||[];const shot=selectedShot();if(stage()==='brief')return `<form id="brief-form" class="panel"><h2>Your film brief</h2><label>Project title<input name="title" value="${esc(p.title)}" maxlength="150" required></label><label>Premise<textarea name="premise" required>${esc(p.premise)}</textarea></label><div class="row"><label>Intended runtime (seconds)<input type="number" name="duration" min="5" max="3600" value="${esc(p.duration||60)}"></label><label>Language<input name="language" value="${esc(p.language||'English')}"></label></div><label>Creative direction<textarea name="direction" placeholder="Naturalistic, restrained, observational…">${esc(p.direction||'')}</textarea></label><div class="actions"><button type="submit">Save brief</button><button type="button" id="prepare-story" class="primary">${state.config.capabilities.planning?'Prepare story':'Write story manually'} →</button></div><p class="muted small">${state.config.capabilities.planning?'Planning uses the configured language model. No image or video generation is started.':'AI planning is not configured. You can create and edit your treatment and shots without simulated AI output.'}</p></form>`;
if(stage()==='story')return screenplayWorkspaceHTML()+(!currentScreenplay(p)?`<details class="panel legacy-story" ${p.story?.treatment?'open':''}><summary>Write a treatment manually</summary><form id="story-form"><h2>Treatment & scenes</h2><label>Treatment<textarea name="treatment" rows="9" placeholder="Write the film’s beginning, turn and ending…">${esc(p.story?.treatment||'')}</textarea></label><label>Scene breakdown<textarea name="scenes" rows="6" placeholder="One scene per line. Include setting, action and story change.">${esc((p.story?.scenes||[]).map(s=>typeof s==='string'?s:(s.description||s.title||s.heading||'')).join('\n'))}</textarea></label><div class="actions"><button type="submit" class="primary">Save story version</button><button type="button" id="approve-story" ${!p.story?.treatment?'disabled':''}>Approve story</button></div><p class="muted small">Approve the saved version. Unsaved edits are not included in the approval.</p></form></details>`:'');
if(stage()==='cast')return renderProductionLibrary(p,state.assets,{approvals:local()?(p.approvals||[]):state.approvals,dependencies:recordDependencies(p)})+`<div class="panel"><h2>Cast & world references</h2><p class="muted">Upload a clear identity master, location or look reference. Choose its role and scope before it enters a production proposal.</p><button id="cast-upload" class="primary">+ Add reference</button></div>${state.assets.length?state.assets.map(a=>`<div class="panel"><h2>${esc(a.name||a.filename)}</h2><p class="small muted">${esc(a.role||'Reference').replaceAll('_',' ')} · ${esc(a.scope||'project')} · Version ${esc(a.version||1)}</p>${assetPreview(a)}<p class="small">Rights, identity consent and model compatibility must be verified before generation.</p><button data-reference="${esc(a.id)}">Mention in Director</button>${state.shot&&/^(image|video)\//.test(a.mime)?`<button data-use-media="${esc(a.id)}">Use for selected shot</button>`:''}</div>`).join(''):'<div class="empty">No references added yet. Your story remains saved.</div>'}`;
if(stage()==='storyboard')return `<div class="panel"><div class="row"><h2 class="shot-sequence-heading">Shot sequence</h2><button id="add-shot">+ Add shot</button></div><p class="muted small">${shots.length} shots · ${shots.reduce((n,s)=>n+(Number(s.duration)||0),0)} seconds planned</p>${shotStrip(shots)}</div>${shot?`<div class="panel"><h2>Storyboard references</h2>${shotReferences(shot)}</div>`+shotEditor(shot):'<div class="empty"><h2>Plan the visual story</h2><p>Add your first shot to define its action, framing and duration.</p></div>'}`;
return `<div class="media-empty"><div class="eyebrow">${stage()==='export'?'Delivery':'Selected shot'}</div><h2>${esc(shot?.title||'No take available')}</h2><p>${stage()==='export'?'No finished film has been rendered. Export becomes available after approved footage, sound and finishing checks.':'No generated take is available. Approved shot requirements and a verified estimate are required before production.'}</p></div>${shot?`<div class="panel"><h2>Uploaded storyboard & references</h2>${shotReferences(shot)}</div>`:''}<div class="panel"><h2>${stage()==='edit'?'Assembly & review':stage()==='export'?'Delivery readiness':'Shot sequence'}</h2>${shotStrip(shots)}${shots.length?'':'<p class="muted small">Create a shot sequence in Storyboard first.</p>'}<div class="actions"><button id="prepare-proposal" ${!shot?'disabled':''}>Prepare shot proposal</button><button disabled title="No generated take is available">Approve take</button></div></div><div class="pending">${stage()==='export'?'Export is blocked until an actual reviewed cut exists. No placeholder download is presented as a finished film.':'Media generation is gated by approved prerequisites, validated model routes, a current estimate and explicit budget authorization.'}</div>`;}
function assetPreview(asset){const url=asset.url;if(!url||!(local()&&url.startsWith('blob:')||url.startsWith(`/api/projects/${encodeURIComponent(state.project.id)}/assets/`)))return '<p class="muted small">Preview unavailable. Reopen the project to retrieve the reference.</p>';if(asset.mime?.startsWith('image/'))return `<img class="asset-preview" src="${esc(url)}" alt="${esc(asset.name||'Uploaded reference')}" loading="lazy">`;if(asset.mime?.startsWith('video/'))return `<video class="asset-preview" controls preload="metadata" src="${esc(url)}" aria-label="${esc(asset.name||'Uploaded video reference')}"></video>`;if(asset.mime?.startsWith('audio/'))return `<audio controls preload="metadata" src="${esc(url)}" aria-label="${esc(asset.name||'Uploaded audio reference')}"></audio>`;return `<a class="small" href="${esc(url)}" download>Download ${esc(asset.name||'reference')}</a>`;}
function shotReferences(shot){const references=state.assets.filter(a=>a.scope==='shot'&&a.shotId===shot.id);return references.length?references.map(a=>`<div class="shot-reference">${assetPreview(a)}<p class="muted small">${esc(a.name)} · ${esc(a.role).replaceAll('_',' ')} · Uploaded reference, not a generated take</p></div>`).join(''):'<p class="muted small">No shot-scoped references yet. Use +, choose “Storyboard / shot reference” and “Selected shot”. Uploaded references stay separate from generated takes.</p>';}
function shotStrip(shots){return `<div class="shot-strip">${shots.map((s,i)=>`<button data-shot="${esc(s.id)}" class="shot-card ${state.shot===s.id?'selected':''}" aria-pressed="${state.shot===s.id}"><strong>${String(i+1).padStart(2,'0')} · ${esc(s.title||'Untitled shot')}</strong><small>${esc(s.duration||0)}s · ${esc(s.status||'draft')}</small></button>`).join('')}</div>`;}
function shotEditor(s){return `<form id="shot-form" class="panel"><h2>Shot specification · v${esc(s.version||1)}</h2><label>Shot title<input name="title" value="${esc(s.title)}" required></label><label>Action & performance<textarea name="description" placeholder="What changes in this shot?">${esc(s.description)}</textarea></label><div class="row"><label>Duration (seconds)<input type="number" name="duration" min="1" max="120" step="0.1" value="${esc(s.duration||5)}" required></label><label>Framing<input name="framing" value="${esc(s.framing||'')}" placeholder="Medium close-up"></label></div><label>Camera & light<textarea name="camera" maxlength="200" placeholder="Position, movement, motivated light…">${esc(s.camera||'')}</textarea></label>${renderProductionBindings(state.project,s)}<label>Locked constraints<textarea name="constraints" placeholder="Identity, wardrobe, exact dialogue, screen direction…">${esc(s.constraints||'')}</textarea></label><div class="actions"><button class="primary" type="submit">Save shot version</button><button type="button" id="approve-shot">Approve storyboard specification</button></div><p class="muted small">Specification approval does not approve generated motion or dialogue.</p></form>`;}
function composer(){return `<form class="composer" id="composer-form"><div id="picker" class="picker" role="listbox" aria-label="Composer suggestions" hidden></div><label for="composer-input" class="skip">Message the Director</label><textarea id="composer-input" placeholder="Describe a change. Use / for skills or @ for references." aria-label="Message the Director" aria-controls="picker" aria-expanded="false">${esc(draft())}</textarea><div class="chips" id="chips"></div><div class="composer-tools"><button type="button" id="attach" aria-label="Upload reference">＋</button><button type="button" id="skills-button">/ Skills</button><button type="button" id="refs-button">@ References</button><button type="button" id="voice-button" aria-label="Voice input unavailable" title="Voice transcription is not configured">Mic</button><button type="submit" class="primary send">Send ↑</button></div></form>`;}
function bindWorkspace(){bindCompactBrief();bindScreenplay();if($('#brief-form')){const button=document.createElement('button');button.type='button';button.id='review-creative-brief';button.textContent='Review creative brief';$('#brief-form').prepend(button);button.onclick=async()=>{const form=$('#brief-form');if(!form.reportValidity())return;const fields=Object.fromEntries(new FormData(form));const dirty=Object.entries(fields).some(([key,value])=>String(state.project[key]??'')!==value);if(!dirty||await saveBrief(form,false))await openCreativeBrief();};}bindProductionLibrary(main,{project:state.project,assets:state.assets,onReview:async command=>{if(command.expectedVersion!==state.project.version)throw Error('This project changed. Reopen it before reviewing.');await reviewArtifact('record:'+command.recordId,command.version,command.decision);render();toast(command.decision==='approved'?'Creative version approved. Rights and media quality still need separate review.':'Creative approval revoked. No media was removed.');},onSave:async command=>{if(local()){const next=applyProductionRecord(state.project,command,state.assets);if(next.version!==state.project.version)state.project=await saveDevice(next,state.project.version);deviceProjects=await listDevice();}else state.project=projectFrom(await api(`/api/projects/${state.project.id}/production-records`,{method:'POST',body:command}));render();toast('Library version saved. Linked shots may need a new review; no media generated.');}});main.querySelectorAll('[data-use-media]').forEach(b=>b.onclick=async()=>{const a=state.assets.find(x=>x.id===b.dataset.useMedia);if(!a||!state.shot)return;const field=a.mime.startsWith('video/')?'clipAssetId':'referenceAssetId';try{await save({shots:state.project.shots.map(s=>s.id===state.shot?{...s,[field]:a.id}:s)});render();toast('Reference selected for this shot. This is uploaded media, not a generated take.');}catch(e){toast(e.message);}});main.querySelectorAll('[data-go]').forEach(b=>b.onclick=async()=>{try{await save({stage:b.dataset.go});render();}catch(e){toast(e.message);}});main.querySelectorAll('[data-stage]').forEach(b=>b.onclick=async()=>{try{await save({stage:b.dataset.stage});render();}catch(e){toast(e.message);}});main.querySelectorAll('[data-shot]').forEach(b=>b.onclick=()=>{if(state.shot!==b.dataset.shot&&draft().trim())state.scopeChanged=true;state.shot=b.dataset.shot;render();});main.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>{if(!state.refs.includes(b.dataset.reference))state.refs.push(b.dataset.reference);renderChips();$('#director').classList.add('open');toast('Reference added to your draft. No generation started.');});$('#rail-upload').onclick=openUpload;if($('#cast-upload'))$('#cast-upload').onclick=openUpload;$('#mobile-project').onclick=()=>$('#rail').classList.toggle('open');$('#mobile-director').onclick=()=>{$('#director').classList.add('open');if(stage()!=='brief')$('#composer-input').focus();};$('#close-director').onclick=()=>{$('#director').classList.remove('open');$('#brief-project-settings')?.setAttribute('aria-expanded','false');(stage()==='brief'?$('#brief-project-settings'):$('#mobile-director'))?.focus();};$('#activity-toggle').onclick=e=>{const hidden=!$('#activity').hidden;$('#activity').hidden=hidden;e.target.setAttribute('aria-expanded',String(!hidden));e.target.textContent=hidden?'View activity':'Hide activity';};
if($('#brief-form')){$('#brief-form').onsubmit=async e=>{e.preventDefault();await saveBrief(e.currentTarget);};$('#prepare-story').onclick=async()=>{const form=$('#brief-form');if(!form.reportValidity())return;if(!await saveBrief(form,false))return;const button=$('#prepare-story');button.disabled=true;button.textContent='Preparing…';try{const context=briefPlanningContext(state.project,local()?state.project.approvals||[]:state.approvals);if(!context.approved||context.stale){if(!context.brief)await changeCreativeBrief({action:'suggest'});button.disabled=false;button.textContent='Continue to story →';await openCreativeBrief();toast('Review and approve your creative brief before continuing to the story.');return;}if(state.config.capabilities.planning){if(!window.confirm('Prepare a story using paid AI planning within the configured planning allowance? This does not generate images, video or audio.')){button.disabled=false;button.textContent='Prepare story →';return;}const data=await api(`/api/projects/${encodeURIComponent(state.project.id)}/plan`,{method:'POST',body:{premise:state.project.premise,authorizePlanning:true}});if(data.project)state.project=data.project;else if(data.id)state.project=data;else state.project=projectFrom(await api(`/api/projects/${encodeURIComponent(state.project.id)}`));}await save({stage:'story'});render();}catch(e){toast(e.message);button.disabled=false;button.textContent='Prepare story →';}};}
if($('#story-form')){$('#story-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await save({story:{...state.project.story,treatment:f.get('treatment'),scenes:f.get('scenes').split('\n').filter(s=>s.trim()).map((description,i)=>({id:`scene-${i+1}`,description}))}});render();toast('Story version saved.');}catch(e){toast(e.message);}};$('#approve-story').onclick=()=>approve('story',state.project.story?.version||state.project.version||1);}
if($('#add-shot'))$('#add-shot').onclick=async()=>{try{const s={id:crypto.randomUUID(),title:`Shot ${(state.project.shots||[]).length+1}`,description:'',duration:5,version:1,status:'draft'};await save({shots:[...(state.project.shots||[]),s]});state.shot=s.id;render();}catch(e){toast(e.message);}};
if($('#shot-form')){$('#shot-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const old=selectedShot();const edited={...old,...Object.fromEntries(f),productionBindings:f.getAll('productionBindings').map(value=>{const [recordId,version]=value.split('@');return {recordId,version:Number(version)};}),duration:Number(f.get('duration')),version:(old.version||1)+1,status:'draft'};try{await save({shots:state.project.shots.map(s=>s.id===old.id?edited:s)});render();toast('New shot version saved. Review it before approval.');}catch(e){toast(e.message);}};$('#approve-shot').onclick=()=>approve(state.shot,selectedShot().version||1);}
if($('#prepare-proposal'))$('#prepare-proposal').onclick=()=>{$('#director').classList.add('open');$('#composer-input').value='Prepare a production proposal for this shot.';saveDraft($('#composer-input').value);$('#composer-input').focus();};
bindComposer();renderChips();}
async function saveBrief(form,notify=true){const fields=Object.fromEntries(new FormData(form));fields.duration=Number(fields.duration);try{await save(fields);$('#project-name').textContent=state.project.title;if(notify){render();toast(local()?'Brief saved on this device.':'Brief saved.');}return true;}catch(e){toast(e.message);return false;}}
async function reviewArtifact(artifactId,version,decision='approved'){
 if(local()){
 if(artifactId==='story'){if(state.project.story.version!==version||decision==='approved'&&!state.project.story.treatment.trim())throw Error('Complete and review the current story version.');}
 else if(!artifactId.startsWith('record:')){const shot=state.project.shots.find(s=>s.id===artifactId);if(!shot||shot.version!==version||decision==='approved'&&!shot.description.trim())throw Error('Complete and review the current shot version.');if(decision==='approved'&&recordDependencies(state.project).shots.find(s=>s.shotId===artifactId)?.holds.length)throw Error('Update linked production versions before review.');}
 if(artifactId.startsWith('record:')){const id=artifactId.slice(7),record=state.project.production?.records?.find(r=>r.id===id);if(!record||record.currentVersion!==version)throw Error('That library version is no longer current.');if(decision==='approved'&&recordDependencies(state.project).records.find(r=>r.recordId===id)?.holds.length)throw Error('Update linked production versions before review.');}
 await save({approvals:[...(state.project.approvals||[]),{artifactId,version,decision,at:new Date().toISOString()}]});return;
 }
 await api(`/api/projects/${encodeURIComponent(state.project.id)}/approvals`,{method:'POST',body:{artifactId,version,decision}});
 state.approvals=list(await api(`/api/projects/${encodeURIComponent(state.project.id)}/approvals`),'approvals');markActivity(`${decision==='approved'?'Approved':'Revoked'} ${artifactId} version ${version}.`);
}
async function approve(artifactId,version){try{await reviewArtifact(artifactId,version);toast(`Version ${version} approved${local()?' in this device draft':''}. This does not authorize generation.`);}catch(e){toast(e.message);}}

function renderChips(){const element=$('#chips');if(!element)return;element.innerHTML=(state.skill?`<button type="button" class="chip" data-remove-skill>/${esc(state.skill.name||state.skill.id)} ×</button>`:'')+state.refs.map(id=>{const a=state.assets.find(x=>x.id===id);return `<button type="button" class="chip" data-remove-ref="${esc(id)}">@${esc(a?.name||a?.filename||'Unavailable reference')} ×</button>`;}).join('');element.querySelector('[data-remove-skill]')?.addEventListener('click',()=>{state.skill=null;renderChips();});element.querySelectorAll('[data-remove-ref]').forEach(b=>b.onclick=()=>{state.refs=state.refs.filter(id=>id!==b.dataset.removeRef);renderChips();});}
function pickerOptions(){const input=$('#composer-input');const before=input.value.slice(0,input.selectionStart);const match=before.match(/(?:^|\s)([/@])([^\s]*)$/);const query=match?.[1]===state.picker?match[2].toLowerCase():'';const options=state.picker==='/'?state.skills:state.assets;return options.filter(o=>`${o.name||o.filename||o.id} ${o.description||''} ${(o.aliases||[]).join(' ')}`.toLowerCase().includes(query));}
function showPicker(kind){state.picker=kind;state.pickerIndex=0;drawPicker();}
function closePicker(){state.picker=null;$('#picker').hidden=true;$('#composer-input').setAttribute('aria-expanded','false');$('#composer-input').removeAttribute('aria-activedescendant');}
function drawPicker(){const box=$('#picker');const options=pickerOptions();if(state.pickerIndex>=options.length)state.pickerIndex=0;box.hidden=false;box.innerHTML=options.length?options.map((o,i)=>`<button type="button" role="option" id="suggestion-${i}" aria-selected="${i===state.pickerIndex}" class="${i===state.pickerIndex?'active':''}" data-option="${i}">${state.picker}${esc(o.name||o.filename||o.id)}<small>${esc(o.description||o.role||'Project reference')}</small></button>`).join(''):`<p>${state.picker==='/'?'No approved skills match your search.':'No project references match. Add one with +.'}</p>`;box.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>selectOption(Number(b.dataset.option)));$('#composer-input').setAttribute('aria-expanded','true');if(options.length)$('#composer-input').setAttribute('aria-activedescendant',`suggestion-${state.pickerIndex}`);}
function selectOption(index){const option=pickerOptions()[index];if(!option)return;const input=$('#composer-input');const start=input.selectionStart;const before=input.value.slice(0,start).replace(/(^|\s)[/@][^\s]*$/, '$1');input.value=before+input.value.slice(start);if(state.picker==='/')state.skill=option;else if(!state.refs.includes(option.id))state.refs.push(option.id);saveDraft(input.value);closePicker();renderChips();input.focus();input.setSelectionRange(before.length,before.length);}
function bindComposer(){const input=$('#composer-input');input.addEventListener('input',e=>{saveDraft(input.value);if(e.isComposing)return;const match=input.value.slice(0,input.selectionStart).match(/(?:^|\s)([/@])[^\s]*$/);if(match){state.picker=match[1];state.pickerIndex=0;drawPicker();}else closePicker();});input.addEventListener('keydown',e=>{if(e.isComposing)return;if(state.picker){if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const count=pickerOptions().length;state.pickerIndex=count?(state.pickerIndex+(e.key==='ArrowDown'?1:-1)+count)%count:0;drawPicker();}else if(e.key==='Enter'){e.preventDefault();selectOption(state.pickerIndex);}else if(e.key==='Escape'){e.preventDefault();closePicker();}else if(e.key==='Tab')closePicker();}else if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('#composer-form').requestSubmit();}});$('#skills-button').onclick=()=>{input.focus();showPicker('/');};$('#refs-button').onclick=()=>{input.focus();showPicker('@');};$('#attach').onclick=openUpload;$('#voice-button').onclick=()=>toast('Voice transcription is not configured. Please type your direction; nothing is recording.');$('#composer-form').onsubmit=async e=>{e.preventDefault();if(state.busy)return;const text=input.value.trim();if(!text){input.focus();return;}if(state.scopeChanged){state.scopeChanged=false;toast('The selected shot changed. Review the context above, then send again.');return;}const referenceIds=[...state.refs];if(referenceIds.some(id=>!state.assets.some(a=>a.id===id))){toast('A reference is unavailable. Remove or reconnect it before sending.');return;}state.busy=true;const button=e.submitter||$('.send');button.disabled=true;button.textContent='Sending…';try{if(local()){const note={role:'You',text};state.messages.push(note);await save({notes:state.messages});markActivity('Direction saved on this device; no AI call made.');saveDraft('');state.skill=null;state.refs=[];render();if(stage()!=='brief')$('#director').classList.add('open');return;}const data=await api(`/api/projects/${encodeURIComponent(state.project.id)}/proposals`,{method:'POST',body:{shotId:state.shot,instruction:text,skillId:state.skill?.id||null,referenceIds}});const proposal=data.proposal||data;state.messages.push({role:'You',text},{role:'Director',text:proposal.summary||proposal.message||proposal.description||'Proposal recorded. Review prerequisites, route eligibility and a verified estimate before generation.'});markActivity('Production proposal prepared. No generation authorized.');saveDraft('');state.skill=null;state.refs=[];render();$('#director').classList.add('open');}catch(e){toast(e.message);button.disabled=false;button.textContent='Send ↑';}finally{state.busy=false;}};}
function openUpload(){if(!state.project)return toast('Create a project before adding private references.');if(!local()&&!state.config.capabilities.uploads)return toast('Uploads are not configured for this environment. Your draft is unchanged.');$('#upload-context').textContent=local()?'Files stay on this device. They are not uploaded to your account or sent to a model.':'References are uploaded to your private workspace. Adding one never starts generation.';$('#upload-limit').textContent=`Limit: ${Math.round((state.config.uploadMaxBytes||2*1024*1024)/1024/1024)} MB.`;$('#upload-dialog').showModal();}
$('#upload-form').onsubmit=async e=>{e.preventDefault();const file=$('#upload-file').files[0];if(!file)return;const max=state.config.uploadMaxBytes||2*1024*1024;if(file.size>max)return toast(`This file exceeds the ${Math.round(max/1024/1024)} MB limit. Choose a smaller file.`);const scope=$('#upload-scope').value;if(scope==='shot'&&!state.shot)return toast('Select a shot first, or use project scope.');const submit=e.submitter;submit.disabled=true;submit.textContent=local()?'Saving…':'Uploading…';try{if(local()){const mime=file.type||(file.name.endsWith('.md')?'text/markdown':'');if(!['image/jpeg','image/png','image/webp','video/mp4','audio/mpeg','audio/wav','application/pdf','text/plain','text/markdown'].includes(mime))throw Error('Choose a supported image, MP4, audio file or document.');await addDeviceAsset(state.project,file,{mime,role:$('#upload-role').value,scope,shotId:scope==='shot'?state.shot:null});state.assets=await loadDeviceAssets(state.project.id);$('#upload-dialog').close();$('#upload-form').reset();render();toast('Reference saved on this device. No upload or generation started.');return;}const buffer=await file.arrayBuffer();let binary='';const bytes=new Uint8Array(buffer);for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const data=await api(`/api/projects/${encodeURIComponent(state.project.id)}/assets`,{method:'POST',body:{name:file.name,mime:file.type||(file.name.toLowerCase().endsWith('.md')?'text/markdown':''),role:$('#upload-role').value,scope,shotId:scope==='shot'?state.shot:null,base64:btoa(binary)}});const asset=data.asset||data;state.assets.push(asset);$('#upload-dialog').close();$('#upload-form').reset();markActivity('Reference uploaded.');render();toast('Reference uploaded. No generation started.');}catch(error){toast(error.message);}finally{submit.disabled=false;submit.textContent='Upload reference';}};
document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>button.closest('dialog').close());
$('#new-button').onclick=()=>{state.project=null;state.skill=null;state.refs=[];state.messages=[];render();};$('#dialog-new').onclick=()=>{$('#projects-dialog').close();$('#new-button').click();};$('#projects-button').onclick=async()=>{try{deviceProjects=await listDevice();if(signedIn())state.projects=list(await api('/api/projects'),'projects');else state.projects=[];const available=[...deviceProjects,...state.projects];$('#project-list').innerHTML=available.length?available.map(p=>`<div class="resume-row"><div><strong>${esc(p.title)}</strong><small>${p.isLocal?'On this device · ':''}${esc(p.stage||'brief')}</small></div><button data-project="${esc(p.id)}">Open</button></div>`).join(''):'<p class="muted">No projects yet. Start with a story.</p>';$('#project-list').querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{$('#projects-dialog').close();loadProject(b.dataset.project);});$('#projects-dialog').showModal();}catch(e){toast(e.message);}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#director')?.classList.remove('open');$('#rail')?.classList.remove('open');}});
$('#auth-button').onclick=async()=>{if(!state.config.user){$('#login-dialog').showModal();return;}try{await api('/api/auth/logout',{method:'POST',body:{}});state.project=null;state.projects=[];state.assets=[];state.messages=[];state.config.user=null;try{localStorage.removeItem('director:lastProject');}catch{}renderAuth();render();toast('Signed out.');}catch(error){toast(error.message);}};
$('#login-form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Signing in…';$('#login-error').textContent='';try{await api('/api/auth/login',{method:'POST',body:{email:$('#login-email').value,password:$('#login-password').value}});$('#login-password').value='';$('#login-dialog').close();await init();toast('Signed in. Your draft is ready.');}catch(error){$('#login-error').textContent=error.message;}finally{button.disabled=false;button.textContent='Sign in';}};
async function init(){try{let config=await api('/api/config');if(!config.user&&config.session?.refreshAvailable){try{await api('/api/auth/refresh',{method:'POST',body:{}});config=await api('/api/config');}catch(error){if(error.status!==401)throw error;}}state.config=config;renderAuth();deviceProjects=await listDevice();$('#mode').textContent=config.mode==='demo'?'Local demo':'Workspace';$('#notice').textContent=config.mode==='demo'?'Local development workspace · no paid generation. Data is stored only in this environment.':!config.user?'Start your brief here. Sign in to save projects and upload private references.':'';if(!signedIn()){state.projects=[];state.skills=localSkills;let last;try{last=localStorage.getItem('director:lastProject');}catch{}if(last?.startsWith('device-')&&deviceProjects.some(p=>p.id===last))await loadProject(last);else render();return;}const [projects,skills]=await Promise.all([api('/api/projects'),api('/api/skills')]);state.projects=list(projects,'projects');state.skills=list(skills,'skills').filter(s=>s.active!==false);let last;try{last=localStorage.getItem('director:lastProject');}catch{}if(last&&[...deviceProjects,...state.projects].some(p=>p.id===last))await loadProject(last);else render();}catch(e){$('#mode').textContent='Offline';$('#notice').textContent=`Connection unavailable: ${e.message} Reload to reconnect. Your local draft is preserved.`;render();}}
async function loadDeviceAssets(id){const assets=await deviceAssets(id);return assets.map(a=>{if(!blobUrls.has(a.id))blobUrls.set(a.id,URL.createObjectURL(a.blob));return {...a,url:blobUrls.get(a.id)};});}
function downloadDraft(){const {isLocal,...project}=state.project;const payload={format:'director-draft-v1',project,references:state.assets.map(({blob,url,...a})=>a),note:'Media files are stored separately. This is a planning document, not a rendered movie.'};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='director-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function saveToWorkspace(){if(!local()||migrationBusy)return;if(!state.config.capabilities.uploads){toast('Cloud saving is not connected yet. Your draft remains on this device.');return;}if(!requireLogin())return;const source=structuredClone(state.project),assets=[...state.assets],button=$('#cloud-save');migrationBusy=true;button.disabled=true;button.textContent='Saving…';try{const cloud=await migrateDeviceDraft({api,project:source,assets,onProgress:toast});if(state.project?.id===source.id&&state.project.version===source.version)await loadProject(cloud.id);toast('Draft, notes and references saved to your workspace. Your device copy remains available. Review imported versions before approval.');}catch(error){toast(`${error.message} Your device copy is safe. Choose Save to workspace again to resume.`);}finally{migrationBusy=false;button.disabled=false;button.textContent='Save to workspace';}}

// Costs are reviewed separately from creative approvals. These actions never enqueue work.
function dollarsToMicros(value){const match=String(value).trim().match(/^(0|[1-9]\d*)(?:\.(\d{1,6}))?$/);if(!match)throw Error('Enter a positive dollar amount with up to six decimal places.');const amount=BigInt(match[1])*1000000n+BigInt((match[2]||'').padEnd(6,'0')||'0');if(amount>BigInt(Number.MAX_SAFE_INTEGER))throw Error('This amount is too large.');return Number(amount);}
function exactDollars(value){if(!Number.isSafeInteger(value)||value<0)return 'Unavailable';const whole=Math.floor(value/1000000);const fraction=String(value%1000000).padStart(6,'0').replace(/0+$/,'');return '$'+whole+(fraction?'.'+fraction:'.00');}
function costTaskLabel(task){return ({image_edit:'Image editing',image_generation:'Image generation',video_generation:'Video generation',reference_video:'Reference video',speech_generation:'Voice generation',music_generation:'Music generation',sound_effects:'Sound effects',lip_sync:'Lip sync',story_reasoning:'Story development',audio_analysis:'Audio analysis',song_analysis:'Song analysis',transcription:'Transcription',alignment:'Audio alignment',stem_separation:'Stem separation',talking_portrait:'Talking portrait',video_edit:'Video editing',video_upscale:'Video upscaling'})[task]||'Creation estimate';}
function costExpiry(value){const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString():'Unknown';}
function costArtifactLabel(value){return value==='story'?'Story':value?.startsWith('record:')?'Library record':state.project?.shots?.find(s=>s.id===value)?.title||'Creative artifact';}
const spendingButton=document.createElement('button');spendingButton.id='project-costs';spendingButton.textContent='Costs';spendingButton.hidden=true;$('.top nav').prepend(spendingButton);
const spendingDialog=document.createElement('dialog');spendingDialog.id='spending-dialog';spendingDialog.setAttribute('aria-labelledby','spending-heading');document.body.append(spendingDialog);
let spendingBusy=false;
function pendingSpending(projectId,kind,body){const storageKey=`director:spending:${projectId}:${kind}`;const signature=JSON.stringify(body);let existing;try{existing=JSON.parse(sessionStorage.getItem(storageKey)||'null');}catch{}if(existing&&existing.signature!==signature)throw Error('A previous request needs checking. Refresh costs and retry the same request before changing its amounts.');if(!existing){existing={signature,requestId:crypto.randomUUID()};sessionStorage.setItem(storageKey,JSON.stringify(existing));}return {storageKey,body:{...body,requestId:existing.requestId}};}
function clearPendingSpending(key){try{sessionStorage.removeItem(key);}catch{}}
async function showSpending(){if(!state.project)return;const projectId=state.project.id;spendingDialog.innerHTML=`<div class="dialog-head"><h2 id="spending-heading">Creation costs</h2><button type="button" id="close-costs" aria-label="Close costs">×</button></div><p><button type="button" id="open-planning-limits">Planning limits</button></p><div id="spending-content" role="status">Loading costs…</div>`;$('#close-costs').onclick=()=>spendingDialog.close();$('#open-planning-limits').onclick=()=>{spendingDialog.close();showPlanningLimits();};if(!spendingDialog.open)spendingDialog.showModal();if(local()){$('#spending-content').innerHTML='<p class="muted">Save this device draft to your workspace before reviewing quotes or setting a spending limit.</p><p class="small">Nothing has been generated or charged.</p>';return;}try{const data=await api(`/api/projects/${encodeURIComponent(projectId)}/spending`);if(state.project?.id!==projectId)return;renderSpending(data,projectId);}catch(error){$('#spending-content').innerHTML=`<p class="error-text">${esc(error.message)}</p><button id="retry-costs" type="button">Refresh costs</button>`;$('#retry-costs').onclick=showSpending;}}
function renderSpending(data,projectId){const quotes=data.quotes||[],authorizations=data.authorizations||[];$('#spending-content').innerHTML=`<p class="muted small">Review estimates and set explicit limits for creation. This view does not show customer billing. Setting a limit does not start generation.</p><p class="pending">${data.generationEnabled?'Generation still requires a separate eligible operation.':'Generation is not enabled. No work will start from this panel.'}</p><h3>Saved estimates</h3>${quotes.length?quotes.map(q=>`<article class="cost-record"><strong>${esc(costTaskLabel(q.task))} · ${exactDollars(q.totalMicroUsd)}</strong><p class="small muted">${esc(costArtifactLabel(q.artifactId))} · version ${esc(q.artifactVersion)} · ${esc(q.modelName||q.modelLabel||'Model details')}<br>Expires ${esc(costExpiry(q.expiresAt))}</p>${Date.parse(q.expiresAt)>Date.now()?`<form data-cost-quote="${esc(q.id)}"><label>Total limit (USD)<input name="max" inputmode="decimal" required placeholder="0.00" value="${esc(exactDollars(q.totalMicroUsd).replace('$',''))}"></label><label>Protected for finishing (USD)<input name="finish" inputmode="decimal" required value="0.00"></label><p class="small muted">The total limit includes the protected finishing amount. Creating media must leave that amount available for finishing.</p><button type="submit" class="primary">Confirm spending limit</button></form>`:'<p class="small">Estimate expired. A fresh verified estimate is required.</p>'}</article>`).join(''):'<p class="muted">No verified estimates yet. A supported model route and current pricing are required before a limit can be set.</p>'}<h3>Spending limits</h3>${authorizations.length?authorizations.map(a=>`<article class="cost-record"><strong>${exactDollars(a.maxMicroUsd)} total limit</strong><p class="small muted">Protected for finishing: ${exactDollars(a.finishReserveMicroUsd)}<br>${a.revokedAt?'Revoked':Date.parse(a.expiresAt)<=Date.now()?'Expired':'Recorded'} · expires ${esc(costExpiry(a.expiresAt))}</p>${!a.revokedAt?`<form data-revoke-authorization="${esc(a.id)}"><label>Reason for revoking<input name="reason" required minlength="5" maxlength="1000" placeholder="Explain why this limit should be revoked"></label><button type="submit">Revoke limit</button></form>`:''}</article>`).join(''):'<p class="muted small">No spending limits recorded.</p>'}${Array.isArray(data.reservations)&&data.reservations.length?`<h3>Creation spending</h3>${data.reservations.map(r=>`<article class="cost-record"><strong>${esc(({held:'Held',unknown:'Unconfirmed',settled:'Actual cost',released:'Released'})[r.chargeState]||'Pending confirmation')}</strong><p class="small muted">${r.chargeState==='settled'?`Actual cost: ${exactDollars(r.actualMicroUsd)}`:`Recorded reservation: ${exactDollars(r.reservedMicroUsd)}`}</p></article>`).join('')}`:''}<p id="spending-status" class="small" role="status" aria-live="polite"></p><button id="refresh-costs" type="button">Refresh costs</button>`;$('#refresh-costs').onclick=showSpending;spendingDialog.querySelectorAll('[data-cost-quote]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();if(spendingBusy)return;try{const maxMicroUsd=dollarsToMicros(form.elements.max.value),finishReserveMicroUsd=dollarsToMicros(form.elements.finish.value);if(maxMicroUsd<=0)throw Error('The total limit must be greater than zero.');const quote=quotes.find(q=>q.id===form.dataset.costQuote);if(!quote||!Number.isSafeInteger(quote.totalMicroUsd)||maxMicroUsd<quote.totalMicroUsd+finishReserveMicroUsd)throw Error('The total limit must cover this estimate plus the protected finishing amount.');const body={expectedVersion:state.project.version,quoteId:form.dataset.costQuote,maxMicroUsd,finishReserveMicroUsd};if(!window.confirm(`Confirm a ${exactDollars(maxMicroUsd)} total limit, including ${exactDollars(finishReserveMicroUsd)} protected for finishing? This does not start generation.`))return;await submitSpending(projectId,'authorize',`/api/projects/${encodeURIComponent(projectId)}/spending-authorizations`,body);}catch(error){$('#spending-status').textContent=error.message;}});spendingDialog.querySelectorAll('[data-revoke-authorization]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();if(spendingBusy)return;const reason=form.elements.reason.value.trim();if(!reason)return;const id=form.dataset.revokeAuthorization;await submitSpending(projectId,`revoke:${id}`,`/api/projects/${encodeURIComponent(projectId)}/spending-authorizations/${encodeURIComponent(id)}/revoke`,{expectedVersion:state.project.version,reason});});}
async function submitSpending(projectId,kind,path,body){let pending;try{pending=pendingSpending(projectId,kind,body);spendingBusy=true;spendingDialog.querySelectorAll('button').forEach(b=>b.disabled=true);$('#spending-status').textContent='Saving your decision…';await api(path,{method:'POST',body:pending.body});clearPendingSpending(pending.storageKey);await showSpending();toast(kind==='authorize'?'Spending limit recorded. No generation started.':'Spending limit revoked.');}catch(error){if(error.status>=400&&error.status<500&&error.status!==408&&error.status!==429&&pending)clearPendingSpending(pending.storageKey);const element=$('#spending-status');if(element)element.textContent=`${error.message} Refresh costs to check the recorded decision. Retrying unchanged uses the same request.`;}finally{spendingBusy=false;spendingDialog.querySelectorAll('button').forEach(b=>b.disabled=false);}}
spendingButton.onclick=showSpending;

const planningDialog=document.createElement('dialog');planningDialog.id='planning-dialog';planningDialog.setAttribute('aria-labelledby','planning-heading');document.body.append(planningDialog);
let planningBusy=false;
function planningMessage(message){const element=$('#planning-status');if(element)element.textContent=message;}
const planningLabels={interpret_brief:'Interpret brief',write_script:'Write script',revise_script:'Revise script',initial_plan:'Prepare production plan',revise_plan:'Revise production plan'};
let planningOperation='interpret_brief',planningLoad=0;
function planningValidConsent(consent,data){return consent.operation===data.operation&&!consent.revokedAt&&Date.parse(consent.expiresAt)>Date.now()&&(!consent.briefScopeHash||consent.briefScopeHash===data.scope?.briefScopeHash)&&(!consent.approvedDecisionDigest||consent.approvedDecisionDigest===data.scope?.approvedDecisionDigest)&&consent.modelId===data.quote?.modelId&&consent.profileFingerprint===data.quote?.profileFingerprint;}
async function showPlanningLimits(operation=planningOperation){
 if(!state.project)return;
 if(typeof operation!=='string'||!Object.hasOwn(planningLabels,operation))operation=planningOperation;
 planningOperation=operation;const projectId=state.project.id,ticket=++planningLoad;
 planningDialog.innerHTML=`<div class="dialog-head"><h2 id="planning-heading">Planning limits</h2><button id="close-planning" type="button" aria-label="Close planning limits">×</button></div><p class="muted small">Choose the work to authorize. Each operation uses its own reviewed model route and allowance. Changing this selection does not start a call or approve a model switch.</p><div id="planning-content">Loading ${esc(planningLabels[operation].toLowerCase())} availability…</div>`;
 $('#close-planning').onclick=()=>planningDialog.close();if(!planningDialog.open)planningDialog.showModal();
 if(local()){$('#planning-content').innerHTML='<p class="muted">Save this device draft to your workspace before setting AI planning limits. You can continue editing manually.</p>';return;}
 try{const data=await api(`/api/projects/${encodeURIComponent(projectId)}/planning/${encodeURIComponent(operation)}`);if(ticket===planningLoad&&state.project?.id===projectId)renderPlanningLimits(data,projectId);}
 catch(error){if(ticket!==planningLoad||state.project?.id!==projectId)return;$('#planning-content').innerHTML=`<p class="error-text">${esc(error.message)}</p><button type="button" id="retry-planning">Refresh planning</button>`;$('#retry-planning').onclick=()=>showPlanningLimits(operation);}
}
function planningRouteHTML(data){const selected=data.route?.selected,modelId=selected?.modelId||data.route?.selectedModelId||data.quote?.modelId;return `<section id="planning-route-summary" class="planning-route-summary"><h3>${esc(planningLabels[data.operation]||data.operation)}</h3>${modelId?`<p><strong>${esc(modelId)}</strong> · ${esc(selected?.provider||'Reviewed provider')}<br><span class="small muted">${esc(selected?.modelVersion||data.quote?.modelVersion||'Version not recorded')} · ${esc(selected?.endpoint||'Endpoint held pending review')}</span></p>`:'<p>No eligible model has been selected for this operation.</p>'}<p class="small muted">Manual editing is free. A reservation is a maximum spending hold, not an expected charge. No automatic model substitution is approved.</p>${data.route?.candidates?.length?`<details><summary>Route review · ${data.route.candidates.length} candidates</summary>${data.route.candidates.map(c=>`<p class="small"><strong>${esc(c.modelId)}</strong> · ${c.eligible?'Eligible':'Held'}${c.holds?.length?'<br>'+esc(c.holds.join('; ')):''}${c.explanation?'<br>'+esc(typeof c.explanation==='string'?c.explanation:JSON.stringify(c.explanation)):''}</p>`).join('')}</details>`:''}</section>`;}
function renderPlanningLimits(data,projectId){
 const operation=data.operation||planningOperation;data={...data,operation};planningOperation=operation;
 const quote=data.quote,consents=data.consents||[],calls=data.calls||[],operations=data.operations?.length?data.operations:Object.entries(planningLabels).map(([id,label])=>({id,label}));
 const quoteValid=quote&&Number.isSafeInteger(quote.maxCallMicroUsd)&&quote.maxCallMicroUsd>0&&Date.parse(quote.expiresAt)>Date.now()&&(!quote.operation||quote.operation===operation);
 const enabled=data.availability?.enabled===true&&data.policy?.path==='llm'&&quoteValid;
 const hasPending=calls.some(c=>['reserved','submitted','running','unknown'].includes(c.status)||c.chargeState==='unknown');
 const scriptBlocked=operation==='write_script'&&!!currentScreenplay(state.project)||operation==='revise_script'&&(!currentScreenplay(state.project)||!screenplayState().revisionRequest);
 $('#planning-content').innerHTML=`<label>Planning operation<select id="planning-operation">${operations.map(o=>`<option value="${esc(o.id)}" ${o.id===operation?'selected':''}>${esc(planningLabels[o.id]||o.label||o.id)}</option>`).join('')}</select></label>${planningRouteHTML(data)}<p class="pending">${esc(data.availability?.reason||data.policy?.reason||(enabled?'This operation is available within its own approved limit.':'No verified route is available for this operation. Continue editing manually.'))}</p>${quoteValid?`<p class="small">Maximum reserved per ${esc(planningLabels[operation]?.toLowerCase()||'planning')} call: <strong>${exactDollars(quote.maxCallMicroUsd)}</strong><br>Estimate expires ${esc(costExpiry(quote.expiresAt))}</p>`:'<p class="muted small">No current verified estimate for this operation. Limits and paid calls remain unavailable.</p>'}${enabled?`<form id="planning-consent-form"><label>Total planning limit (USD)<input name="max" inputmode="decimal" required value="${esc(exactDollars(quote.maxCallMicroUsd).slice(1))}"></label><label>Protected for finishing (USD)<input name="finish" inputmode="decimal" required value="0.00"></label><label>Maximum planning calls<input name="calls" type="number" min="1" max="10" step="1" required value="1"></label><p class="small muted">This limit authorizes ${esc(planningLabels[operation]?.toLowerCase())} only, using the displayed model. The total includes the protected finishing amount. Confirming does not start a call.</p><button type="submit" class="primary">Approve ${esc(planningLabels[operation]?.toLowerCase())} limit</button></form>`:''}<h3>Planning approvals</h3>${consents.length?consents.map(c=>`<article class="cost-record"><strong>${esc(planningLabels[c.operation]||'Legacy planning allowance')} · ${exactDollars(c.maxMicroUsd)} total</strong><p class="small muted">Up to ${esc(c.maxCalls)} calls while budget remains · ${esc(c.modelId||'Model binding recorded server-side')}<br>Protected for finishing: ${exactDollars(c.finishReserveMicroUsd)}<br>${c.revokedAt?'Revoked':planningValidConsent(c,data)?'Recorded for this operation and current brief':c.operation!==operation?'For another operation':'Expired or project/model decisions changed'} · expires ${esc(costExpiry(c.expiresAt))}</p>${enabled&&planningValidConsent(c,data)&&!hasPending?`<div class="actions"><button type="button" data-planning-call="${esc(c.id)}" data-operation="${esc(operation)}" ${scriptBlocked?'disabled':''}>${esc(planningLabels[operation])}</button></div>${scriptBlocked?'<p class="small muted">An existing script requires a saved explicit revision request. Select Revise script after saving it.</p>':'<p class="small muted">Results are proposals. Your approved content stays protected.</p>'}`:''}${!c.revokedAt?`<form data-revoke-planning="${esc(c.id)}"><label>Reason for revoking<input name="reason" required minlength="5" maxlength="1000"></label><button type="submit">Revoke planning approval</button></form>`:''}</article>`).join(''):'<p class="muted small">No planning approval recorded.</p>'}<h3>Planning calls</h3>${calls.length?calls.map(c=>`<article class="cost-record"><strong>${esc(planningLabels[c.operation]||'Planning call')}</strong><p class="small">${esc(({reserved:'Reserved',submitted:'Submitted',running:'In progress',unknown:'Checking outcome',completed:c.planError?'Needs attention':'Ready for review',failed:'Failed',cancelled:'Cancelled'})[c.status]||'Status recorded')}</p>${c.operation==='interpret_brief'&&c.status==='completed'&&!c.planError?`<button type="button" data-review-brief-proposal="${esc(c.id)}">Review brief proposal</button>`:''}${['write_script','revise_script'].includes(c.operation)&&c.status==='completed'&&!c.planError?`<button type="button" data-review-screenplay-proposal="${esc(c.id)}">Review script proposal</button>`:''}${c.planError?`<p class="small error-text">${esc(String(c.planError).slice(0,400))}</p>`:''}${c.status==='unknown'||c.chargeState==='unknown'?'<p class="small muted">Outcome or usage is unconfirmed. Check the original call before making another request.</p>':''}${c.status==='reserved'?`<div class="actions">${enabled&&c.operation===operation?`<button type="button" data-resume-planning="${esc(c.id)}">Resume unstarted call</button>`:''}<button type="button" data-release-planning="${esc(c.id)}">Cancel unstarted call</button></div>`:''}${(['submitted','running','unknown'].includes(c.status)||c.chargeState==='unknown')?`<button type="button" data-poll-planning="${esc(c.id)}">Check status</button>`:''}</article>`).join(''):'<p class="muted small">No planning calls recorded. Approving a limit does not create one.</p>'}<p id="planning-status" role="status" aria-live="polite"></p><button type="button" id="refresh-planning">Refresh planning</button>`;
 $('#planning-operation').onchange=event=>showPlanningLimits(event.target.value);$('#refresh-planning').onclick=()=>showPlanningLimits(operation);
 planningDialog.querySelectorAll('[data-review-brief-proposal]').forEach(button=>button.onclick=async()=>{try{const result=await api(`/api/projects/${projectId}/planning-calls/${encodeURIComponent(button.dataset.reviewBriefProposal)}`);if(state.project?.id!==projectId)return;planningDialog.close();await openCreativeBrief({callId:button.dataset.reviewBriefProposal,result:result.result});}catch(error){planningMessage(error.message);}});
 planningDialog.querySelectorAll('[data-review-screenplay-proposal]').forEach(button=>button.onclick=async()=>{try{await openScreenplayProposal(button.dataset.reviewScreenplayProposal);planningDialog.close();}catch(error){planningMessage(error.message);}});
 const form=$('#planning-consent-form');if(form)form.onsubmit=async event=>{event.preventDefault();if(planningBusy)return;try{const maxMicroUsd=dollarsToMicros(form.elements.max.value),finishReserveMicroUsd=dollarsToMicros(form.elements.finish.value),maxCalls=Number(form.elements.calls.value);if(!Number.isInteger(maxCalls)||maxCalls<1||maxCalls>10)throw Error('Choose between one and ten planning calls.');if(BigInt(maxMicroUsd)<BigInt(quote.maxCallMicroUsd)+BigInt(finishReserveMicroUsd))throw Error('The total must cover one call plus the protected finishing amount.');if(!window.confirm(`Approve ${exactDollars(maxMicroUsd)} for up to ${maxCalls} ${planningLabels[operation].toLowerCase()} calls using ${quote.modelId||data.route?.selectedModelId}, including ${exactDollars(finishReserveMicroUsd)} protected for finishing? No call starts yet.`))return;await submitPlanning(projectId,`consent:${operation}`,`/api/projects/${encodeURIComponent(projectId)}/planning-consents`,{expectedVersion:state.project.version,operation,expectedModelId:quote.modelId,expectedProfileFingerprint:quote.profileFingerprint,maxMicroUsd,finishReserveMicroUsd,maxCalls});}catch(error){planningMessage(error.message);}};
 planningDialog.querySelectorAll('[data-revoke-planning]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();await submitPlanning(projectId,`revoke:${form.dataset.revokePlanning}`,`/api/projects/${encodeURIComponent(projectId)}/planning-consents/${encodeURIComponent(form.dataset.revokePlanning)}/revoke`,{expectedVersion:state.project.version,reason:form.elements.reason.value.trim()});});
 planningDialog.querySelectorAll('[data-planning-call]').forEach(button=>button.onclick=async()=>{if(!window.confirm(`Use one approved ${planningLabels[operation].toLowerCase()} call with the displayed model to prepare a proposal? Approved content is not replaced.`))return;await submitPlanning(projectId,`call:${button.dataset.planningCall}:${operation}`,`/api/projects/${encodeURIComponent(projectId)}/planning-calls`,{expectedVersion:state.project.version,consentId:button.dataset.planningCall,operation});});
 planningDialog.querySelectorAll('[data-poll-planning]').forEach(button=>button.onclick=()=>submitPlanning(projectId,`poll:${button.dataset.pollPlanning}`,`/api/projects/${encodeURIComponent(projectId)}/planning-calls/${encodeURIComponent(button.dataset.pollPlanning)}/poll`,{}));
 planningDialog.querySelectorAll('[data-resume-planning],[data-release-planning]').forEach(button=>button.onclick=()=>{const resume=!!button.dataset.resumePlanning,id=button.dataset.resumePlanning||button.dataset.releasePlanning;if(!window.confirm(resume?'Resume this unstarted call using its existing reservation? No new reservation is created.':'Cancel this unstarted call and release its unused hold?'))return;return submitPlanning(projectId,`${resume?'resume':'release'}:${id}`,`/api/projects/${encodeURIComponent(projectId)}/planning-calls/${encodeURIComponent(id)}/${resume?'resume':'release'}`,{expectedVersion:state.project.version});});
}

async function submitPlanning(projectId,kind,path,body){
 if(planningBusy)return;let pending;const controls=Array.from(planningDialog.querySelectorAll('button,input,select,textarea'),node=>({node,disabled:node.disabled}));
 try{pending=pendingSpending(projectId,'planning:'+kind,body);planningBusy=true;controls.forEach(({node})=>node.disabled=true);planningMessage('Recording your request…');await api(path,{method:'POST',body:pending.body});clearPendingSpending(pending.storageKey);if(state.project?.id!==projectId)return;await showPlanningLimits();toast(kind.startsWith('consent:')?'Operation-specific planning limit recorded. No call started.':kind.startsWith('revoke:')?'Planning approval revoked.':kind.startsWith('poll:')?'Planning status checked.':'Planning request recorded. Review its status before making another request.');}
 catch(error){const rejected=error.status>=400&&error.status<500&&error.status!==408&&error.status!==429;if(rejected&&pending)clearPendingSpending(pending.storageKey);if(state.project?.id!==projectId)return;planningMessage(`${error.message} Refresh planning to check the original request. An unchanged retry keeps the same request ID.`);if(pending&&!rejected){const retry=document.createElement('button');retry.type='button';retry.id='retry-same-planning-request';retry.textContent='Retry same request';retry.onclick=()=>submitPlanning(projectId,kind,path,body);$('#planning-status')?.append(retry);}}
 finally{planningBusy=false;controls.forEach(({node,disabled})=>{if(node.isConnected)node.disabled=disabled;});}
}


let compactEditing=null,compactBusy=false,compactProjectId=null;const compactDrafts=new Map();
function compactBriefState(){const approvals=local()?state.project.approvals||[]:state.approvals;const context=briefPlanningContext(state.project,approvals);return {...context,display:!context.brief||context.stale?suggestBrief(state.project,approvals):context.brief};}
function briefDisplayValue(value){if(Array.isArray(value))return value.join(', ');return value==null?'':String(value);}
function compactBriefHTML(){if(compactProjectId!==state.project.id){compactProjectId=state.project.id;compactEditing=compactDrafts.get(compactProjectId)?.field||null;}const context=compactBriefState(),fields=context.display.fields;const value=key=>briefDisplayValue(fields[key]?.value);const known=Object.keys(briefLabels).filter(key=>value(key)&&!['purpose','format','duration','language'].includes(key));return `<section id="compact-brief" class="compact-brief"><div class="compact-heading"><small>${context.approved?'Approved direction':'Your direction'}</small><span class="brief-origin">${fields.purpose?.status==='explicit'?'Your choice':'Suggested'}</span></div><p class="compact-purpose">${esc((value('purpose')||state.project.premise).slice(0,320))}${(value('purpose')||state.project.premise).length>320?'…':''}</p><div class="brief-chips"><span>${esc(({short_film:'Short film',music_video:'Music video',advertisement:'Advertisement'})[value('format')]||value('format'))}</span><span>${esc(value('duration'))} seconds</span><span>${esc(value('language'))}</span>${state.project.direction?`<span>${esc(state.project.direction)}</span>`:''}</div>${['visualStyle','tone'].filter(key=>value(key)).map(key=>`<div class="compact-creative-choice"><div><strong>${key==='visualStyle'?'Look':'Tone'}</strong><span class="brief-origin">${fields[key]?.status==='explicit'?'Your choice':'Suggested'}</span></div><p>${esc(value(key).slice(0,220))}${value(key).length>220?'…':''}</p>${value(key).length>220?`<details><summary>Read full ${key==='visualStyle'?'look':'tone'}</summary><p>${esc(value(key))}</p></details>`:''}</div>`).join('')}<div class="actions"><button type="button" data-edit-brief-field="purpose" ${compactEditing?'disabled':''}>Edit direction</button><button type="button" data-edit-brief-field="tone" ${compactEditing?'disabled':''}>${value('tone')?'Edit tone':'Add tone'}</button></div>${compactEditing?compactEditorHTML(compactEditing,fields[compactEditing]):''}<details class="brief-context-details"><summary>Choices & assumptions</summary><p class="small muted">Suggested details remain suggestions after approval. Optional choices can wait until they matter.</p><details class="brief-source-idea"><summary>Original idea</summary><p class="compact-premise">${esc(state.project.premise)}</p></details>${['purpose','format','duration','language',...known].map(key=>`<div class="compact-choice"><div><strong>${esc(briefLabels[key])}</strong><p>${esc(value(key))}</p><small>${fields[key]?.status==='explicit'?'Your choice':'Suggested'}${fields[key]?.evidence?.length?' · '+esc(fields[key].evidence.join('; ')):''}</small></div><button type="button" data-edit-brief-field="${key}" ${compactEditing?'disabled':''}>Change</button></div>`).join('')}<label class="compact-add-detail">Add an optional detail<select id="compact-add-detail" ${compactEditing?'disabled':''}><option value="">Choose a detail…</option>${Object.entries(briefLabels).map(([key,label])=>`<option value="${key}">${esc(label)}</option>`).join('')}</select></label><p class="small muted">Casting, voice, locations and other optional details can also wait until their production stage.</p><button type="button" id="compact-ai-interpret">Explore AI interpretation</button></details>${(context.display.departmentPlan||[]).length?`<details class="brief-handoffs"><summary>Production handoffs</summary>${context.display.departmentPlan.map(item=>`<article><strong>${esc(item.department)}</strong><p>${esc(item.task)}</p><small>${item.status==='needs_input'?'Needs input':'Ready for planning'} · Not executed</small></article>`).join('')}</details>`:''}<div class="actions compact-primary">${context.approved?`<button type="button" id="continue-direction" class="primary" ${compactEditing?'disabled':''}>Continue to story →</button>`:`<button type="button" id="approve-direction" class="primary" ${compactEditing?'disabled':''}>Approve direction</button>`}</div><p class="small muted">${context.approved?'You can change this direction later; changes need a new review.':'Approval includes the visible suggestions and deferred choices. It does not start a paid call.'}</p><p id="compact-brief-status" role="status"></p></section>`;}
function compactEditorHTML(key,field){const saved=compactDrafts.get(state.project.id);const text=saved?.field===key?saved.value:briefDisplayValue(field?.value);return `<form id="compact-field-editor" class="compact-editor" data-field="${esc(key)}"><label>${esc(briefLabels[key])}${key==='format'?`<select name="value">${[['short_film','Short film'],['music_video','Music video'],['advertisement','Advertisement']].map(([id,label])=>`<option value="${id}" ${text===id?'selected':''}>${label}</option>`).join('')}</select>`:`<textarea name="value" maxlength="2000" rows="3">${esc(text)}</textarea>`}</label><div class="actions"><button type="submit">Save this change</button><button type="button" id="cancel-brief-field">Cancel</button></div></form>`;}
function bindCompactBrief(){if(!$('#compact-brief'))return;$('#brief-project-settings').onclick=()=>{$('#director').classList.add('open');$('#brief-project-settings').setAttribute('aria-expanded','true');$('#close-director').focus();};$('#compact-add-detail').onchange=event=>{if(!event.target.value||compactBusy)return;compactEditing=event.target.value;compactDrafts.set(state.project.id,{field:compactEditing,value:briefDisplayValue(compactBriefState().display.fields[compactEditing]?.value)});render();$('#compact-field-editor [name=value]')?.focus();};main.querySelectorAll('[data-edit-brief-field]').forEach(button=>button.onclick=()=>{if(compactEditing||compactBusy)return;compactEditing=button.dataset.editBriefField;compactDrafts.set(state.project.id,{field:compactEditing,value:briefDisplayValue(compactBriefState().display.fields[compactEditing]?.value)});render();$('#compact-field-editor [name=value]')?.focus();});if($('#cancel-brief-field'))$('#cancel-brief-field').onclick=()=>{const key=compactEditing;compactDrafts.delete(state.project.id);compactEditing=null;render();$(`[data-edit-brief-field="${key}"]`)?.focus();};if($('#compact-ai-interpret'))$('#compact-ai-interpret').onclick=()=>showPlanningLimits('interpret_brief');const form=$('#compact-field-editor');if(form)form.elements.value.oninput=()=>compactDrafts.set(state.project.id,{field:form.dataset.field,value:form.elements.value.value});if(form)form.onsubmit=event=>{event.preventDefault();const key=form.dataset.field,text=form.elements.value.value;compactAction(async()=>{const context=compactBriefState();if(!context.brief||context.stale)await changeCreativeBrief({action:'suggest'});await changeCreativeBrief({action:'update',changes:{[key]:!text.trim()?null:key==='duration'?Number(text):text}});compactDrafts.delete(state.project.id);compactEditing=null;render();$(`[data-edit-brief-field="${key}"]`)?.focus();toast('Direction updated. Review and approve the new version.');});};if($('#approve-direction'))$('#approve-direction').onclick=()=>compactAction(async()=>{if(compactEditing)throw Error('Save or cancel your visible edit first.');let context=compactBriefState();if(!context.brief||context.stale)await changeCreativeBrief({action:'suggest'});const version=currentBrief(state.project).version,body={artifactId:'brief',version,decision:'approved',acknowledgeAssumptions:true};if(local()){assertBriefApproval(state.project,body);await save({approvals:[...(state.project.approvals||[]),{...body,at:new Date().toISOString()}]});}else{await api(`/api/projects/${state.project.id}/approvals`,{method:'POST',body});state.approvals=list(await api(`/api/projects/${state.project.id}/approvals`),'approvals');}render();toast('Direction approved. No paid generation started.');});if($('#continue-direction'))$('#continue-direction').onclick=()=>compactAction(async()=>{if(compactEditing)throw Error('Save or cancel your visible edit first.');const context=compactBriefState();if(!context.approved||context.stale)throw Error('Review your updated direction before continuing.');await save({stage:'story'});render();});}
async function compactAction(action){if(compactBusy)return;compactBusy=true;const controls=Array.from(document.querySelectorAll('#main button,#main input,#main textarea,#main select,.top nav button'),node=>({node,disabled:node.disabled}));controls.forEach(({node})=>node.disabled=true);try{await action();}catch(error){const status=$('#compact-brief-status');if(status)status.textContent=error.message;else toast(error.message);}finally{compactBusy=false;controls.forEach(({node,disabled})=>{if(node.isConnected)node.disabled=disabled;});}}
const creativeBriefDialog=document.createElement('dialog');creativeBriefDialog.id='creative-brief-dialog';creativeBriefDialog.setAttribute('aria-labelledby','creative-brief-heading');document.body.append(creativeBriefDialog);
let creativeBriefBusy=false;
const briefLabels={purpose:'Creative intent',audience:'Audience',audienceResponse:'Desired audience response',platform:'Platform',aspectRatio:'Aspect ratio',visualStyle:'Visual style',tone:'Emotion & tone',setting:'Setting',cast:'Casting',voice:'Voice & delivery',product:'Product',constraints:'Creative constraints',budget:'Budget direction',format:'Format',duration:'Duration',language:'Language'};
async function changeCreativeBrief(command){if(local()){const next=applyBriefCommand(state.project,{expectedVersion:state.project.version,...command},state.project.approvals||[]);state.project=await saveDevice(next,state.project.version);deviceProjects=await listDevice();return briefPlanningContext(state.project,state.project.approvals||[]);}const data=await api(`/api/projects/${state.project.id}/brief`,{method:'POST',body:{expectedVersion:state.project.version,...command}});state.project=data.project;return data.briefContext;}
async function openCreativeBrief(proposal=null){if(!proposal){try{const context=briefPlanningContext(state.project,local()?state.project.approvals||[]:state.approvals);if(stage()!=='brief')await save({stage:'brief'});render();$('#compact-brief')?.scrollIntoView({block:'nearest'});}catch(error){toast(error.message);}return;}const id=state.project.id;let context;try{context=local()?briefPlanningContext(state.project,state.project.approvals||[]):(await api(`/api/projects/${id}/brief`)).briefContext;}catch(error){toast(error.message);return;}creativeBriefDialog.innerHTML=`<div class="dialog-head"><h2 id="creative-brief-heading">Creative brief</h2><button type="button" id="close-creative-brief" aria-label="Close creative brief">×</button></div><div id="creative-brief-content"></div>`;$('#close-creative-brief').onclick=()=>creativeBriefDialog.close();if(!creativeBriefDialog.open)creativeBriefDialog.showModal();renderCreativeBrief(context,proposal);creativeBriefDialog.scrollTop=0;}
function previewBriefProposal(result){try{const proposal=result?.briefProposal||result;const approvals=local()?state.project.approvals||[]:state.approvals;const baseline=currentBrief(state.project)||suggestBrief(state.project,approvals);const projected=applyBriefCommand(structuredClone(state.project),{expectedVersion:state.project.version,action:'apply_proposal',proposal},approvals);const after=currentBrief(projected);const entries=Object.entries(after.fields).filter(([key,field])=>Object.hasOwn(briefLabels,key)&&field.status!=='unknown'&&field.value!==null&&field.value!==''&&(!Array.isArray(field.value)||field.value.length>0)&&JSON.stringify(field.value)!==JSON.stringify(baseline.fields[key]?.value));return {entries};}catch{return {entries:[],invalid:true};}}
function renderCreativeBrief(context,proposal){const preview=previewBriefProposal(proposal.result);$('#creative-brief-content').innerHTML=`<p class="muted small">Review the changes to your direction. Confirmed choices and direct corrections remain protected.</p>${briefProposalHTML(preview)}<div class="actions"><button type="button" id="apply-brief-proposal" class="primary" ${preview.invalid||!preview.entries.length?'disabled':''}>Apply proposal for review</button></div><p id="creative-brief-status" role="status"></p>`;$('#apply-brief-proposal').onclick=()=>{if(!preview.entries.length||preview.invalid)return;return runBriefAction(async()=>{const data=await api(`/api/projects/${state.project.id}/brief/apply-proposal`,{method:'POST',body:{expectedVersion:state.project.version,callId:proposal.callId}});state.project=data.project;creativeBriefDialog.close();if(stage()!=='brief')await save({stage:'brief'});render();toast('Proposal applied. Review and approve your updated direction.');});};}
function briefProposalHTML(preview){if(preview.invalid)return '<p class="small">This proposal cannot be safely compared with the current brief. Refresh your project and review a current interpretation.</p>';if(!preview.entries.length)return '<p class="small">No changes to your current direction.</p>';return `<div class="brief-proposal">${preview.entries.map(([key,field])=>`<article class="cost-record"><strong>${esc(briefLabels[key])}</strong><p>${esc(briefDisplayValue(field.value))}</p><p class="small muted">Suggested change</p>${field.evidence?.length?`<p class="small muted">${esc(field.evidence.filter(x=>typeof x==='string').join('; '))}</p>`:''}</article>`).join('')}</div><p class="small muted">Only these changes will enter a new review version. Your protected choices stay in place.</p>`;}
async function runBriefAction(action){if(creativeBriefBusy)return;creativeBriefBusy=true;creativeBriefDialog.querySelectorAll('button').forEach(button=>button.disabled=true);try{await action();}catch(error){const status=$('#creative-brief-status');if(status)status.textContent=error.message;}finally{creativeBriefBusy=false;creativeBriefDialog.querySelectorAll('button').forEach(button=>button.disabled=false);const context=briefPlanningContext(state.project,local()?state.project.approvals||[]:state.approvals);if($('#approve-creative-brief'))$('#approve-creative-brief').disabled=context.stale||context.approved;}}
// A script is reviewed as a readable document. Editing opens one focused field.
const screenplayDrafts=new Map();
let screenplayBusy=false;
const screenplayApprovals=()=>local()?(state.project.approvals||[]):state.approvals;
const screenplayState=()=>screenplayContext(state.project,screenplayApprovals());
function scriptDocumentHTML(document){if(!document)return '';const names=new Map((document.characters||[]).map(c=>[c.id,c.name]));return `<article class="screenplay-document"><header><h2>${esc(document.title)}</h2>${document.logline?`<p class="script-logline">${esc(document.logline)}</p>`:''}</header>${document.treatment?`<details class="script-treatment"><summary>Treatment</summary><p>${esc(document.treatment)}</p></details>`:''}${document.characters?.length?`<details class="script-characters"><summary>Characters · ${document.characters.length}</summary>${document.characters.map(c=>`<p><strong>${esc(c.name)}</strong> ${esc(c.description)}</p>`).join('')}</details>`:''}${(document.scenes||[]).map((scene,i)=>`<section class="script-scene" data-script-scene="${esc(scene.id)}"><header><h3>${esc(scene.heading)}</h3><span class="small muted" title="Estimated scene duration">${i+1} · ~${esc(scene.durationSeconds)}s</span></header><p class="script-action">${esc(scene.action)}</p>${(scene.dialogue||[]).map(line=>`<div class="script-dialogue"><strong>${esc(names.get(line.characterId)||line.characterId)}</strong>${line.direction?`<small>(${esc(line.direction)})</small>`:''}<p>${esc(line.text)}</p></div>`).join('')}</section>`).join('')}<p class="small muted">Scene timings are estimates; voice timing is measured later.</p></article>`;}
function scriptFieldOptions(document){const fields=[{key:'title',label:'Script title',value:document.title},{key:'logline',label:'Logline',value:document.logline},{key:'treatment',label:'Treatment',value:document.treatment}];for(const [i,c] of document.characters.entries()){fields.push({key:`characters.${i}.name`,label:`${c.name} · name`,value:c.name},{key:`characters.${i}.description`,label:`${c.name} · description`,value:c.description});}for(const [i,s] of document.scenes.entries()){fields.push({key:`scenes.${i}.heading`,label:`Scene ${i+1} · heading`,value:s.heading},{key:`scenes.${i}.action`,label:`Scene ${i+1} · action`,value:s.action},{key:`scenes.${i}.durationSeconds`,label:`Scene ${i+1} · seconds`,value:s.durationSeconds});for(const [j,line] of s.dialogue.entries())fields.push({key:`scenes.${i}.dialogue.${j}.text`,label:`Scene ${i+1} · dialogue ${j+1}`,value:line.text},{key:`scenes.${i}.dialogue.${j}.direction`,label:`Scene ${i+1} · delivery ${j+1}`,value:line.direction});}return fields;}
function screenplayEditorHTML(draft,context){if(!draft)return '';if(draft.mode==='source')return `<form id="script-source-form" class="script-focused-editor"><h3>Add your script</h3><p class="small muted">The saved source keeps your exact original text. It is used as the working script only when you choose that action.</p><label>Source title<input name="title" required maxlength="200" value="${esc(draft.title||'My script')}"></label><label>${typeof draft.rawText==='string'?'Uploaded original · read-only preview':'Script text'}<textarea name="text" ${typeof draft.rawText==='string'?'readonly':''} required rows="12" maxlength="100000">${esc(draft.text||'')}</textarea></label><label>Declared use<select name="permittedUse">${[['reference_only','Reference only'],['user_owned','I own this script'],['adaptation','I have permission to adapt']].map(([key,label])=>`<option value="${key}" ${draft.permittedUse===key?'selected':''}>${label}</option>`).join('')}</select></label><p class="small muted">Your declaration is recorded; it is not independent verification of rights.</p><div class="actions"><button type="submit" class="primary">Preserve original</button><button type="button" data-cancel-script-edit>Cancel</button></div></form>`;
 if(draft.mode==='field'){const options=scriptFieldOptions(context.screenplay.document),dirty=String(draft.value??'')!==String(options.find(f=>f.key===draft.field)?.value??'');return `<form id="script-field-form" class="script-focused-editor"><h3>Edit script</h3><label>What to change<select name="field" ${dirty?'disabled':''}>${options.map(f=>`<option value="${esc(f.key)}" ${draft.field===f.key?'selected':''}>${esc(f.label)}</option>`).join('')}</select></label><label>Updated text<textarea name="value" rows="7" maxlength="60000">${esc(draft.value)}</textarea></label><div class="actions"><button type="submit" class="primary">Save script version</button><button type="button" data-cancel-script-edit>Cancel</button></div></form>`;}
 if(draft.mode==='review')return `<form id="script-finding-form" class="script-focused-editor"><h3>Record permitted use</h3><p class="small">Record why you are entitled to use this matched passage. Revising the passage is also available through Edit script.</p><label>Permission or ownership explanation<textarea name="note" required minlength="5" maxlength="1000" rows="4">${esc(draft.note||'')}</textarea></label><div class="actions"><button type="submit">Record explanation</button><button type="button" data-cancel-script-edit>Cancel</button></div></form>`;
 return `<form id="screenplay-revision-form" class="script-focused-editor"><h3>Request a script revision</h3><label>What should change?<textarea name="instruction" required maxlength="2000" rows="4">${esc(draft.instruction||'')}</textarea></label><fieldset><legend>Scenes to revise</legend><p class="small muted">Leave all unchecked to request a whole-script revision. Selected scenes preserve the other scenes.</p>${context.screenplay.document.scenes.map((s,i)=>`<label class="script-check"><input type="checkbox" name="sceneIds" value="${esc(s.id)}" ${(draft.sceneIds||[]).includes(s.id)?'checked':''}><span>${i+1}. ${esc(s.heading)}</span></label>`).join('')}</fieldset><div class="actions"><button type="submit" class="primary">Save revision request</button><button type="button" data-cancel-script-edit>Cancel</button></div><p class="small muted">Saving is free. Run the saved request separately within an approved planning limit.</p></form>`;}
function screenplayOriginalityHTML(context){const report=context.originality;if(!report)return '';const dispositions=context.review?.dispositions||[],findings=report.findings||[];return `<section class="script-originality" aria-labelledby="script-originality-heading"><h3 id="script-originality-heading">Originality review</h3><p>${report.coverage?.status==='unavailable'?'Comparison coverage unavailable: no project source text to compare.':`Checked against ${esc(report.coverage?.sourceCount||0)} project source${report.coverage?.sourceCount===1?'':'s'} only.`}</p><p class="small muted">External scripts, translated copying and plot similarity are not checked. This report does not establish legal clearance.</p><details class="script-coverage-details"><summary>What this check covers</summary><p class="small">Phrase matching starts at 8 words, 40 characters and 6 distinct words. Near-verbatim matching uses bounded edits within longer passages. Short quotations and semantic or translated copying are outside this check.</p></details>${findings.length?`<details open><summary>${findings.length} passage match${findings.length===1?'':'es'} to review</summary>${findings.map(f=>{const recorded=dispositions.some(d=>d.findingKey===f.key&&d.decision==='authorized_use');return `<article class="script-finding"><strong>${esc(f.sourceTitle)} · ${esc(String(f.kind).replaceAll('_',' '))}</strong><blockquote>${esc(f.scriptExcerpt)}</blockquote><p class="small muted">Source: ${esc(f.sourceExcerpt)}</p>${recorded?'<p class="small">Permitted-use explanation recorded for this version.</p>':`<button type="button" data-review-script-finding="${esc(f.key)}">Record permitted use</button>`}</article>`;}).join('')}</details>`:report.coverage?.status!=='unavailable'?'<p class="small">No matches detected within this coverage.</p>':''}${report.truncated?'<p class="small error-text">Comparison limits were reached. Resolve this incomplete review before approval.</p>':''}</section>`;}
function screenplayWorkspaceHTML(){const context=screenplayState(),snapshot=context.screenplay,draft=screenplayDrafts.get(state.project.id),sourceList=context.sources||[];return `<section id="screenplay-workspace" class="panel screenplay-workspace"><header class="script-workspace-head"><div><h2>${snapshot?'Your script':'From your idea to a script'}</h2><p class="small muted">${snapshot?`Version ${esc(snapshot.version)} · ${esc(({llm_generated:'AI-generated draft',user_supplied:'User-supplied script',mixed:'Edited script'})[snapshot.provenance?.kind]||'Script draft')} · ${context.approved?'Approved':context.stale?'Source or direction changed · review required':'Needs review'}`:'The Director writes from your approved film direction. Uploading a script is optional.'}</p></div><button type="button" id="write-script" ${draft?'disabled':''}>${snapshot?'AI planning & proposals':'Write script with AI'}</button></header>${!snapshot?'<p class="small muted">Writing starts only after you review availability, approve a planning limit and choose Write script. No paid call starts here.</p>':''}${snapshot&&!draft?`<div class="actions script-secondary-actions">${context.stale?'<button type="button" id="refresh-screenplay-context">Keep this script & recheck</button>':''}<button type="button" id="edit-screenplay">Edit script</button><button type="button" id="revise-screenplay">Request AI revision</button></div>`:''}${draft?screenplayEditorHTML(draft,context):''}${snapshot?scriptDocumentHTML(snapshot.document)+screenplayOriginalityHTML(context):''}${context.revisionRequest?`<details class="script-saved-revision"><summary>Saved revision request</summary><p>${esc(context.revisionRequest.instruction)}</p><p class="small muted">${context.revisionRequest.sceneIds.length?`${context.revisionRequest.sceneIds.length} selected scenes`:'Whole script'} · Run through AI planning & proposals.</p></details>`:''}${!draft?`<details class="script-sources"><summary>${sourceList.length?`Original sources · ${sourceList.length}`:'Have your own script?'} <span class="small muted">Optional</span></summary><p class="small muted">Add .txt or .md text, or paste a script. PDF and Word import are not supported here.</p><label class="script-upload-label" for="script-source-file">Upload text script<input type="file" id="script-source-file" accept=".txt,.md,text/plain,text/markdown"></label><button type="button" id="paste-script-source">Paste script</button>${sourceList.map(s=>`<article class="script-source"><strong>${esc(s.title)}</strong><p class="small muted">${esc(s.permittedUse.replaceAll('_',' '))} · original retained</p><details><summary>View original</summary><pre>${esc(s.text)}</pre></details>${snapshot?'<p class="small muted">Reference retained. Edit the working script or save an explicit revision request to develop it.</p>':`<button type="button" data-use-script-source="${esc(s.id)}">Use as working script</button>`}</article>`).join('')}</details>`:''}${snapshot?`<div class="script-approval"><label class="script-check"><input type="checkbox" id="screenplay-coverage-ack" ${context.approved?'checked disabled':''}><span>I understand this comparison has limited coverage and does not prove the script is original.</span></label><div class="actions"><button type="button" id="approve-screenplay" ${draft||context.approved||context.stale?'disabled':''}>${context.approved?'Script approved':'Approve this script version'}</button><button type="button" id="continue-screenplay" class="primary" ${draft||!context.approved||context.stale?'disabled':''}>Continue to cast & world →</button></div></div>`:''}<p id="screenplay-status" role="status" aria-live="polite"></p></section>`;}
async function changeScreenplay(command){const projectId=state.project.id,expectedVersion=state.project.version;let next;if(local())next=await commandScreenplayDevice(state.project,{expectedVersion,...command});else next=projectFrom(await api(`/api/projects/${encodeURIComponent(projectId)}/screenplay`,{method:'POST',body:{expectedVersion,...command}}));if(state.project?.id!==projectId)throw Error('The script was saved to its project. Reopen that project to review it.');state.project=next;if(local())deviceProjects=await listDevice();return screenplayState();}
async function screenplayAction(action){if(screenplayBusy)return;screenplayBusy=true;const controls=Array.from(document.querySelectorAll('#main button,#main input,#main textarea,#main select,.top nav button'),node=>({node,disabled:node.disabled}));controls.forEach(({node})=>node.disabled=true);try{await action();}catch(error){const status=$('#screenplay-status');if(status)status.textContent=error.message;else toast(error.message);}finally{screenplayBusy=false;controls.forEach(({node,disabled})=>{if(node.isConnected)node.disabled=disabled;});}}
function openScriptEditor(draft){if(screenplayBusy||screenplayDrafts.has(state.project.id))return;screenplayDrafts.set(state.project.id,{...draft,screenplayVersion:currentScreenplay(state.project)?.version||0});render();$('#screenplay-workspace .script-focused-editor textarea')?.focus();}
function bindScreenplay(){if(!$('#screenplay-workspace'))return;const projectId=state.project.id;$('#write-script').onclick=()=>showPlanningLimits(currentScreenplay(state.project)&&screenplayState().revisionRequest?'revise_script':'write_script');$('#refresh-screenplay-context')?.addEventListener('click',()=>screenplayAction(async()=>{await changeScreenplay({action:'save',document:currentScreenplay(state.project).document});render();toast('Script retained as a new version against the current direction and sources. Review before approving.');}));if($('#edit-screenplay'))$('#edit-screenplay').onclick=()=>openScriptEditor({mode:'field',field:'treatment',value:currentScreenplay(state.project).document.treatment});if($('#revise-screenplay'))$('#revise-screenplay').onclick=()=>openScriptEditor({mode:'revision',instruction:'',sceneIds:[]});$('#paste-script-source')?.addEventListener('click',()=>openScriptEditor({mode:'source',title:'My script',text:'',permittedUse:'reference_only'}));$('#script-source-file')?.addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{if(!/\.(txt|md)$/i.test(file.name))throw Error('Choose a .txt or .md script. PDF and Word import are not supported.');if(file.size>300000)throw Error('Choose a text script smaller than 300 KB.');let text;try{text=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer());}catch{throw Error('Save this script as UTF-8 text and upload it again.');}if(text.length>100000)throw Error('The script can contain at most 100,000 characters.');if(state.project?.id!==projectId)return;openScriptEditor({mode:'source',title:file.name,text,rawText:text,permittedUse:'reference_only'});}catch(error){toast(error.message);}finally{event.target.value='';}});main.querySelectorAll('[data-cancel-script-edit]').forEach(button=>button.onclick=()=>{screenplayDrafts.delete(projectId);render();$('#edit-screenplay')?.focus();});main.querySelectorAll('[data-use-script-source]').forEach(button=>button.onclick=()=>screenplayAction(async()=>{if(currentScreenplay(state.project))throw Error('A working script already exists. Use Edit script or request a revision.');await changeScreenplay({action:'use_source',sourceId:button.dataset.useScriptSource});render();toast('Original retained. Review the new working script and its source matches.');}));
 const sourceForm=$('#script-source-form');if(sourceForm){sourceForm.oninput=()=>{const draft=screenplayDrafts.get(projectId);draft.title=sourceForm.elements.title.value;draft.permittedUse=sourceForm.elements.permittedUse.value;if(typeof draft.rawText!=='string')draft.text=sourceForm.elements.text.value;};sourceForm.onsubmit=event=>{event.preventDefault();const draft=screenplayDrafts.get(projectId),source={title:sourceForm.elements.title.value,permittedUse:sourceForm.elements.permittedUse.value,text:typeof draft.rawText==='string'?draft.rawText:sourceForm.elements.text.value};screenplayAction(async()=>{await changeScreenplay({action:'add_source',source});screenplayDrafts.delete(projectId);render();toast('Original text preserved. Choose Use as working script if you want to develop it.');});};}
 const fieldForm=$('#script-field-form');if(fieldForm){fieldForm.elements.field.onchange=()=>{const draft=screenplayDrafts.get(projectId);draft.field=fieldForm.elements.field.value;draft.value=String(scriptFieldOptions(currentScreenplay(state.project).document).find(f=>f.key===draft.field)?.value??'');fieldForm.elements.value.value=draft.value;};fieldForm.elements.value.oninput=()=>{const draft=screenplayDrafts.get(projectId);draft.value=fieldForm.elements.value.value;const original=scriptFieldOptions(currentScreenplay(state.project).document).find(f=>f.key===draft.field)?.value;fieldForm.elements.field.disabled=draft.value!==String(original??'');};fieldForm.onsubmit=event=>{event.preventDefault();const draft={...screenplayDrafts.get(projectId)};screenplayAction(async()=>{const current=currentScreenplay(state.project);if(current.version!==draft.screenplayVersion)throw Error('The script changed while you were editing. Your typed change is retained; reopen the current version before applying it.');const document=structuredClone(current.document),parts=draft.field.split('.'),key=parts.pop();let target=document;for(const part of parts)target=target[part];target[key]=key==='durationSeconds'?Number(draft.value):draft.value;await changeScreenplay({action:'save',document});screenplayDrafts.delete(projectId);render();toast('New script version saved. Original sources and earlier versions remain available.');});};}
 const revisionForm=$('#screenplay-revision-form');if(revisionForm){revisionForm.oninput=()=>{const draft=screenplayDrafts.get(projectId);draft.instruction=revisionForm.elements.instruction.value;draft.sceneIds=Array.from(revisionForm.querySelectorAll('[name=sceneIds]:checked'),node=>node.value);};revisionForm.onsubmit=event=>{event.preventDefault();const revisionRequest={instruction:revisionForm.elements.instruction.value,sceneIds:Array.from(revisionForm.querySelectorAll('[name=sceneIds]:checked'),node=>node.value)};screenplayAction(async()=>{const draft=screenplayDrafts.get(projectId);if(currentScreenplay(state.project).version!==draft.screenplayVersion)throw Error('The script changed. Review the current scenes before saving this request.');await changeScreenplay({action:'set_revision',revisionRequest});screenplayDrafts.delete(projectId);render();toast('Revision request saved. Review a planning limit before running it.');});};}
 main.querySelectorAll('[data-review-script-finding]').forEach(button=>button.onclick=()=>openScriptEditor({mode:'review',findingKey:button.dataset.reviewScriptFinding,note:''}));const findingForm=$('#script-finding-form');if(findingForm){findingForm.elements.note.oninput=()=>screenplayDrafts.get(projectId).note=findingForm.elements.note.value;findingForm.onsubmit=event=>{event.preventDefault();const draft={...screenplayDrafts.get(projectId)};screenplayAction(async()=>{if(currentScreenplay(state.project).version!==draft.screenplayVersion)throw Error('The script changed. Review the current finding before recording your explanation.');const existing=screenplayState().review?.dispositions||[];await changeScreenplay({action:'record_review',dispositions:[...existing.filter(d=>d.findingKey!==draft.findingKey),{findingKey:draft.findingKey,decision:'authorized_use',note:draft.note}]});screenplayDrafts.delete(projectId);render();toast('Explanation recorded for this comparison. It does not establish legal clearance.');});};}
 $('#approve-screenplay')?.addEventListener('click',()=>screenplayAction(async()=>{if(screenplayDrafts.has(projectId))throw Error('Save or cancel your visible change before approval.');if(!$('#screenplay-coverage-ack').checked)throw Error('Acknowledge the comparison coverage before approving this script.');const context=screenplayState(),body={artifactId:'screenplay',version:context.screenplay.version,expectedVersion:state.project.version,decision:'approved',acknowledgeLimitedCoverage:true};assertScreenplayApproval(state.project,body,screenplayApprovals());if(local())await save({approvals:[...(state.project.approvals||[]),{...body,at:new Date().toISOString()}]});else{await api(`/api/projects/${encodeURIComponent(projectId)}/approvals`,{method:'POST',body});state.approvals=list(await api(`/api/projects/${encodeURIComponent(projectId)}/approvals`),'approvals');}render();toast('Script version approved. No media generation started.');}));$('#continue-screenplay')?.addEventListener('click',()=>screenplayAction(async()=>{const context=screenplayState();if(screenplayDrafts.has(projectId)||!context.approved||context.stale)throw Error('Review and approve the current script before continuing.');await save({stage:'cast'});render();}));}
const screenplayProposalDialog=document.createElement('dialog');screenplayProposalDialog.id='screenplay-proposal-dialog';screenplayProposalDialog.setAttribute('aria-labelledby','screenplay-proposal-heading');document.body.append(screenplayProposalDialog);
let screenplayProposalBusy=false;
screenplayProposalDialog.addEventListener('cancel',event=>{if(screenplayProposalBusy)event.preventDefault();});
async function openScreenplayProposal(callId){
 const projectId=state.project.id;
 if(screenplayDrafts.has(projectId))throw Error('Save or cancel your visible script edit before reviewing a proposal.');
 const data=await api(`/api/projects/${encodeURIComponent(projectId)}/planning-calls/${encodeURIComponent(callId)}`);
 if(state.project?.id!==projectId)return;
 const candidate=data.result?.screenplay?.document||data.result?.screenplay;
 if(!candidate||!Array.isArray(candidate.scenes)||!Array.isArray(candidate.characters))throw Error('No complete screenplay proposal is available for this call.');
 screenplayProposalDialog.innerHTML=`<div class="dialog-head"><h2 id="screenplay-proposal-heading">Review script proposal</h2><button type="button" id="close-screenplay-proposal" aria-label="Close script proposal">×</button></div><p class="small muted">This proposal has not replaced your script. Applying creates a version requiring originality review and approval.</p>${scriptDocumentHTML(candidate)}<div class="actions"><button type="button" id="apply-screenplay-proposal" class="primary">Apply script for review</button></div><p id="screenplay-proposal-status" role="status" aria-live="polite"></p>`;
 $('#close-screenplay-proposal').onclick=()=>{if(!screenplayProposalBusy)screenplayProposalDialog.close();};
 $('#apply-screenplay-proposal').onclick=async()=>{
  if(screenplayProposalBusy)return;
  screenplayProposalBusy=true;
  const controls=Array.from(document.querySelectorAll('#main button,#main input,#main textarea,#main select,.top nav button,#screenplay-proposal-dialog button'),node=>({node,disabled:node.disabled}));
  controls.forEach(({node})=>node.disabled=true);
  let appliedProject=null;
  try{
   if(state.project?.id!==projectId)throw Error('Reopen this project to apply its proposal.');
   if(screenplayDrafts.has(projectId))throw Error('Save or cancel your visible edit first.');
   const result=await api(`/api/projects/${encodeURIComponent(projectId)}/screenplay/apply-proposal`,{method:'POST',body:{expectedVersion:state.project.version,callId}});
   if(state.project?.id!==projectId)return;
   const applied=projectFrom(result);state.project=applied;appliedProject=applied;
   if(applied.stage!=='story'){
    const staged=await api(`/api/projects/${encodeURIComponent(projectId)}`,{method:'PATCH',body:{stage:'story',expectedVersion:applied.version}});
    if(state.project?.id!==projectId)return;
    state.project=projectFrom(staged);
   }
   screenplayProposalDialog.close();render();toast('Script proposal applied. Review its originality coverage before approval.');
  }catch(error){if(appliedProject&&state.project?.id===projectId){screenplayProposalDialog.close();render();toast('Script saved. Could not open Story. Choose Story in project stages to continue.');}else if(state.project?.id===projectId){$('#screenplay-proposal-status').textContent=error.message;}}
  finally{screenplayProposalBusy=false;controls.forEach(({node,disabled})=>{if(node.isConnected)node.disabled=disabled;});}
 };
 if(!screenplayProposalDialog.open)screenplayProposalDialog.showModal();
 screenplayProposalDialog.scrollTop=0;
}
init();
